function completeHighSchoolEntry(options = {}) {
  const state = player?.schoolInvitationState;
  const invitationValidation = validateSchoolInvitationSet(state);
  if (!invitationValidation.ok) {
    showNotice("高中邀請資料不完整，暫時不能進入高中主篇。", "error");
    return false;
  }
  const directStartBypass = state.compatibilityMode === "direct-start-bypass";
  if (!directStartBypass && state.selectionFinalized !== true) {
    showNotice("請先確認一間高中，再進入高中主篇。", "warning");
    return false;
  }
  if (!directStartBypass && !state.selectedSchoolRoster) {
    materializeSelectedHighSchoolRoster(player, { rosterRole: "bench" });
  }
  if (player.chapter === "青棒" && Number(player.age) === 16) return true;
  const schoolContext = getSelectedHighSchoolContext(player);
  applyChapterBreather();
  player.chapter = "青棒";
  player.age = 16;
  player.highSchoolStep = 0;
  player.highSchoolPositionPreference = player.primaryPosition || "";
  player.highSchoolRoleCode = "";
  player.highSchoolCompetitionEvaluation = null;
  player.highSchoolOpportunityHistory = [];
  player.highSchoolNextOpportunity = null;
  player.highSchoolYearOneStartingRole = "";
  player.highSchoolYearOneMatchHistory = [];
  player.highSchoolYearOneComplete = false;
  player.highSchoolMatch = createInitialPlayer().highSchoolMatch;
  player.highSchoolAzheEcho = createInitialPlayer().highSchoolAzheEcho;
  player.highSchoolRivalContext = createInitialPlayer().highSchoolRivalContext;
  const schoolName = schoolContext?.schoolName || state.legacyExistingSchool?.schoolName || player.highSchoolRoute;
  showNotice(`你進入${schoolName}，高中棒球正式開始。`, "success");
  showCurrentEvent();
  return true;
}

function createHighSchoolPlayingTimeOpportunity(options = {}) {
  if (typeof PlayingTimeGameExposure === "undefined") return null;
  const requestedPosition = options.requestedPosition || player.primaryPosition || "內野手";
  const school = getHighSchoolPlayingTimeSchoolContext(player);
  const readinessSnapshot = createHighSchoolOpportunityReadinessSnapshot(requestedPosition, player);
  const opportunityIndex = Math.max(1, Number(options.opportunityIndex) || 1);
  const schoolYearIdentity = player.schoolInvitationState?.selectedSchoolYearRosterIdentity?.identity
    || `${school.schoolId}|legacy-high-school-year-one`;
  const highSchoolYear = Math.max(1, Math.min(3, Math.floor(Number(options.highSchoolYear) || 1)));
  const yearPhase = highSchoolYear === 1 ? "high-school-year-one" : `high-school-year-${highSchoolYear}`;
  const opportunityPhase = options.opportunityPhase || (opportunityIndex === 1 ? "autumn-exhibition" : "post-autumn-evaluation");
  const resolved = PlayingTimeGameExposure.resolveStartingOpportunity({
    matchId: options.matchId,
    readinessSnapshot,
    opportunitySeed: [player.capabilityState?.settlementId || player.capabilityState?.version || "capability", schoolYearIdentity, yearPhase, opportunityPhase, opportunityIndex, options.matchId || "match"].join("|"),
    actualRole: options.actualRole,
    projectedRole: school.projectedRole,
    playingTimeEnvironment: school.playingTimeEnvironment,
    competitionDepth: school.competitionDepth,
    positionNeed: school.positionNeed,
    coachUsageStyle: school.coachStyle,
    evaluationTrend: options.evaluationTrend,
    previousActualExposure: options.previousActualExposure,
    coachTrust: options.includeDynamicReadiness ? player.relationships?.coachTrust : undefined,
    health: options.includeDynamicReadiness ? player.body : undefined,
    stableVariationSeed: options.stableVariationSeed,
    directStartForced: options.directStartForced === true,
    gameContext: { gameType: "highSchoolExhibition", inning: 0, expectedGameImportance: "regular", importance: "regular", leverage: "normal", scoreMargin: 0 }
  });
  if (!options.preserveDecisionId) return resolved;
  return Object.freeze({
    ...cloneSchoolInvitationValue(resolved),
    decisionId: options.preserveDecisionId,
    opportunitySeed: options.preserveOpportunitySeed || resolved.opportunitySeed
  });
}

function prepareHighSchoolYearOneMatch(options = {}) {
  assertHighSchoolMatchCapabilityAdmission(player);
  if (options.matchContext && typeof MatchContextFoundation === "undefined") throw new Error("Explicit match context requires MatchContextFoundation");
  const targetMatchId = options.matchId || "hs-y1-autumn-exhibition";
  const targetEventId = options.eventId || "high_school_showcase";
  const highSchoolYear = Math.max(1, Math.min(3, Math.floor(Number(options.highSchoolYear) || 1)));
  const opportunityIndex = Math.max(1, Number(options.opportunityIndex) || 1);
  if (player.highSchoolMatch?.id === targetMatchId) {
    const match = player.highSchoolMatch;
    if (options.matchContext) {
      if (!match.matchContext) throw new Error("Existing match has no explicit context; cannot reassign a started match");
      const requested = MatchContextFoundation.normalizeMatchContext({...match.matchContext, ...options.matchContext});
      if (JSON.stringify(requested) !== JSON.stringify(match.matchContext)) throw new Error("Existing match context cannot change");
    }
    if (match.completed || (typeof match.simulationPhase === "string" && match.rosters?.home?.lineup?.length === 9 && match.rosters?.away?.lineup?.length === 9)) {
      match.currentMomentId = getHighSchoolYearOneMomentId(match);
      if (!match.completed && match.currentDomain === "defense" && isInfieldDecisionFamilyPosition(match.developmentPositionOverride || match.position) && match.defensiveSituation?.familyId !== "infield") {
        buildInfieldMeaningfulMoment(match, player);
        match.currentAssignment = getHighSchoolDefensiveSituationText(match);
        setHighSchoolCoachTacticalDirection(match);
      }
      return match;
    }
  }
  const code = ["starter", "rotation", "bench"].includes(player.highSchoolRoleCode) ? player.highSchoolRoleCode : "bench";
  if (highSchoolYear === 1 && !player.highSchoolYearOneStartingRole) player.highSchoolYearOneStartingRole = code;
  const roleAssignments = {
    starter: { lineupStatus: "starter", entryWindowInning: 1, history: `以${player.primaryPosition || "守備"}先發，從開賽起進入守備與打序` },
    rotation: { lineupStatus: "bench", entryWindowInning: 4, history: `本場先從板凳待命，預計在中段代打並接替${player.primaryPosition || "守備"}` },
    bench: { lineupStatus: "bench", entryWindowInning: 5, history: `本場先從板凳觀察，等待中後段代打與短局守備機會` }
  };
  const position = player.primaryPosition || "內野手";
  const requestedDevelopmentPosition = opportunityIndex === 1 && infieldPositions.includes(pendingHighSchoolMatchPositionOverride)
    ? pendingHighSchoolMatchPositionOverride : "";
  if (requestedDevelopmentPosition && !isDevelopmentTestPositionLegalForThrowingHand(requestedDevelopmentPosition, player.throws, player.age)) {
    throw new Error(getDevelopmentTestPositionLegalityMessage(requestedDevelopmentPosition, player.throws));
  }
  const developmentPositionOverride = requestedDevelopmentPosition;
  const suppliedOpportunity = options.opportunityDecision || null;
  const simulationSeed = suppliedOpportunity
    ? createHighSchoolMatchSimulationSeedFromIdentity(suppliedOpportunity.decisionId || suppliedOpportunity.matchId)
    : createHighSchoolMatchSimulationSeed();
  const directStartForced = highSchoolYear === 1 && opportunityIndex === 1
    && Array.isArray(player.flags) && player.flags.includes("direct_start_history");
  const opportunityDecision = suppliedOpportunity || createHighSchoolPlayingTimeOpportunity({
    matchId: targetMatchId,
    actualRole: code,
    requestedPosition: developmentPositionOverride || position,
    directStartForced,
    opportunityIndex,
    opportunityPhase: options.opportunityPhase || "autumn-exhibition",
    highSchoolYear
  });
  if ((suppliedOpportunity || opportunityIndex > 1) && (!opportunityDecision || opportunityDecision.matchId !== targetMatchId)) {
    throw new Error(`高中第 ${highSchoolYear} 年第 ${opportunityIndex} 次實戰必須直接消費相同 match identity 的既有 Opportunity。`);
  }
  if (opportunityDecision && typeof HighSchoolCompetitionReassessment !== "undefined") {
    player.highSchoolOpportunityHistory = HighSchoolCompetitionReassessment.recordOpportunity(player.highSchoolOpportunityHistory, {
      opportunity: opportunityDecision,
      opportunityIndex,
      roleAtCreation: code
    });
  }
  const plannedAppearance = opportunityDecision?.plannedUsage?.appearanceType || (code === "starter" ? "start" : "lateGameAppearance");
  const starts = plannedAppearance === "start";
  const roleAssignment = opportunityDecision
    ? {
      lineupStatus: starts ? "starter" : "bench",
      entryWindowInning: starts ? 1 : Math.max(5, Number(opportunityDecision.plannedUsage.entryInning) || 5),
      history: getHighSchoolPlayingTimeAssignmentText(opportunityDecision)
    }
    : roleAssignments[code];
  const assignedPosition = opportunityDecision?.assignedPosition || developmentPositionOverride || position;
  const developmentTestCapabilityOverride = developmentPositionOverride
    ? createDevelopmentMatchPositionTestCapabilityOverride(developmentPositionOverride, player) : null;
  const selectedSchoolRoster = materializeSelectedHighSchoolRoster(player, {
    rosterRole: starts ? "starter" : "bench",
    playerPosition: assignedPosition
  });
  const rosters = createHighSchoolMatchSimulationRoster(
    starts ? "starter" : code === "starter" ? "bench" : code,
    assignedPosition,
    simulationSeed,
    selectedSchoolRoster,
    options.opponentRosterId || "regional-power-school"
  );
  const matchContext = typeof MatchContextFoundation !== "undefined" ? MatchContextFoundation.createMatchContext({
    matchId: targetMatchId,
    playerTeamId: rosters.home.teamRoster?.teamId || "home",
    opponentTeamId: rosters.away.teamRoster?.teamId || "away",
    matchOrigin: options.matchType === "final-competition" ? "officialCompetition" : "developmentMatch",
    legacyFallback: !options.matchContext,
    ...options.matchContext
  }) : null;
  if (matchContext && (matchContext.matchId !== targetMatchId || matchContext.playerTeamId !== (rosters.home.teamRoster?.teamId || "home") || matchContext.opponentTeamId !== (rosters.away.teamRoster?.teamId || "away"))) throw new Error("Match context / roster identity mismatch");
  if (matchContext && MatchContextFoundation.isPlayerAway(matchContext)) [rosters.home, rosters.away] = [rosters.away, rosters.home];
  const playerSide = matchContext ? MatchContextFoundation.playerSide(matchContext) : "home";
  const playerLineupSlot = rosters[playerSide].lineup.findIndex(item => item.id === "player");
  const resolvedCompetitionRules = typeof CompetitionRules !== "undefined"
    ? CompetitionRules.resolveMatchCompetitionRules(matchContext)
    : null;
  const regulationInnings = resolvedCompetitionRules?.rules.regulationInnings
    || Math.max(1, Number(player.highSchoolMatch?.regulationInnings) || 7);
  player.highSchoolMatch = {
    id: targetMatchId,
    matchContext,
    ...(resolvedCompetitionRules ? {
      ruleSetId: resolvedCompetitionRules.ruleSetId,
      rules: resolvedCompetitionRules.rules,
      ruleSetWarning: resolvedCompetitionRules.warning
    } : {}),
    ...(options.scheduleCompetitionRefs || {}),
    eventId: targetEventId,
    matchType: options.matchType || "autumn-exhibition",
    highSchoolYear,
    opportunityIndex,
    opponent: options.opponent || "高橋所屬的地區強校",
    inning: 1,
    half: "上",
    outs: 0,
    scores: { home: 0, away: 0 },
    runners: [null, null, null],
    role: code,
    position,
    assignment: roleAssignment.history,
    matchEntryHistory: `${roleAssignment.history}；${formatHandedness(player.bats, player.throws)}`,
    currentAssignment: starts ? (playerSide === "home" ? "比賽從一局上開始；先完成守備，再等待打序輪到你。" : "比賽從一局上開始；依打序完成進攻，再進入守備。") : "比賽從一局上開始；你在板凳觀察，但場上每個打席都會完整進行。",
    offenseTeam: "away",
    defenseTeam: "home",
    currentBatter: rosters.away.lineup[0]?.id || "",
    battingOrderIndex: { home: 0, away: 0 },
    tiebreakHalfInitialization: null,
    halfInningResolved: false,
    simulationPhase: "full_match_flow",
    simulationCursor: 0,
    simulationSeed,
    simulationLog: [],
    presentedEventCursor: 0,
    scoreboardRevealHalfIndex: 0,
    regulationInnings,
    lineScore: { home: [], away: [] },
    gameRecord: null,
    rosters,
    playerLineupStatus: roleAssignment.lineupStatus,
    playerLineupSlot,
    playerFieldingAssignment: starts ? assignedPosition : "",
    playerEntryWindowInning: roleAssignment.entryWindowInning,
    playerEntryCompleted: starts,
    performanceEvidence: {},
    matchExperience: null,
    gameExposureState: opportunityDecision && typeof PlayingTimeGameExposure !== "undefined"
      ? PlayingTimeGameExposure.createGameExposureState(opportunityDecision) : null,
    developmentFullMatchStart: pendingHighSchoolFullMatchTest,
    playerRunnerLocation: -1,
    momentIndex: 0,
    currentMomentId: highSchoolYearOneMomentIds[0],
    currentDomain: "flow",
    coachTacticalDirection: { domain: "", intent: "", riskPreference: "", priority: "", sourceCoachId: "", presentationStyle: "" },
    coachTacticalContextSignature: "",
    opponentTacticalTruth: { code: "", targetRunnerId: "" },
    ballContext: { type: "", family: "", pace: "", label: "", detail: "", timeWindow: "" },
    positionDecisionFamily: "", currentFieldingPosition: starts && (developmentPositionOverride || opportunityDecision?.positionFallbackApplied) ? assignedPosition : "", developmentPositionOverride,
    developmentTestCapabilityOverride, defensiveSituation: {},
    matchDecisionDensityState: createHighSchoolMatchDecisionDensityState(),
    pitcherRuntimeState: null,
    pitcherSequencingDebugTrace: [],
    pitcherObservableHistory: [],
    pitcherTacticalSequenceHistory: [],
    pitcherTacticalDebugTrace: [],
    batterAnticipationState: null,
    prePitchPlanningState: null,
    offensivePlateAppearanceState: null,
    pendingOffensiveOpportunity: null,
    offensivePlayerAgencyState: null,
    offensiveTacticalActionState: null,
    offensiveBuntPAState: null,
    buntBallInPlayState: null,
    pendingDefensiveResumeState: null,
    lastDefensiveResolution: { resultCode: "", tier: "", decisionQuality: "", executionQuality: "", primaryCause: "", secondaryCause: "", causeExplanation: "" },
    pendingHalfInningTermination: null,
    catcherDecisionState: null,
    catcherReassessmentTrigger: null,
    completedMoments: [],
    playerContribution: { strong: 0, mixed: 0, failure: 0, runsCreated: 0, runsScored: 0, hits: 0, walks: 0, outsCreated: 0, errors: 0 },
    previousMomentDecision: "",
    previousMomentOutcome: "",
    passage: "",
    opponentAdjustment: "",
    coachInstruction: starts ? "先跟著比賽完成每個守備與打席。" : "先讀完整比賽流；被叫到時直接接進當下局面。",
    decision: "",
    outcomeTier: "",
    outcome: "",
    consequence: "",
    coachReaction: "現任教練確認你的第一個場上任務。",
    teamReaction: "休息區把下一段比賽交到你手上。",
    performanceSummary: "",
    teamResult: "",
    settled: false,
    pendingGameSettlement: "",
    eventSettlementApplied: false,
    developmentPresentationCompleted: false,
    completed: false
  };
  ensureHighSchoolPitcherRuntimeState(player.highSchoolMatch);
  if (isHighSchoolMatchOpportunityDebugMode()) ensureHighSchoolMatchOpportunityTrace(player.highSchoolMatch);
  setHighSchoolCoachTacticalDirection(player.highSchoolMatch);
  recordHighSchoolMatchSimulationEvent(player.highSchoolMatch, {
    type: "matchEntry", inning: 1, half: "上",
    outs: 0, runners: player.highSchoolMatch.runners,
    scores: player.highSchoolMatch.scores,
    assignment: player.highSchoolMatch.matchEntryHistory
  });
  pendingHighSchoolMatchPositionOverride = "";
  pendingHighSchoolFullMatchTest = false;
  player.highSchoolRoleContext.assignment = roleAssignment.history;
  return player.highSchoolMatch;
}

// Match opportunities are school-to-school fixtures, separate from PlayingTimeGameExposure decisions.

function shouldEnterHighSchoolMatchPlayer(match) {
  if (match && !match.playerEntryCompleted && match.playerLineupStatus === "bench") {
    const assignedPosition = match.gameExposureState?.opportunitySnapshot?.assignedPosition
      || match.developmentPositionOverride || match.playerFieldingAssignment || match.position;
    const incumbent = getCurrentHighSchoolMatchDefender(match, getHighSchoolPlayerTeamSide(match), assignedPosition);
    if (!incumbent) throw new Error("Active defense integrity failed: missing substitution incumbent");
    if (match.rosters[getHighSchoolPlayerTeamSide(match)].lineup[Number(match.battingOrderIndex?.[getHighSchoolPlayerTeamSide(match)]) || 0] !== incumbent) return false;
  }
  const exposureState = match?.gameExposureState;
  if (exposureState) {
    if (exposureState.pitcherExposureDeferred || exposureState.plannedUsage?.appearanceType === "noAppearance") return false;
    const opportunity = exposureState.opportunitySnapshot || {};
    const margin = Math.abs(getHighSchoolPlayerScoreDifference(match));
    const coachStyle = opportunity.coachUsageStyle || "balanced";
    const actualRole = opportunity.actualRole || match.role || "bench";
    const contextAllowsEntry = coachStyle === "developmental"
      || actualRole === "starter"
      || (coachStyle === "conservative" ? margin >= 3 : coachStyle === "performanceFirst" ? actualRole === "rotation" || margin <= 2 : actualRole === "rotation" || margin >= 2);
    if (!contextAllowsEntry || match.inning < 5) return false;
  }
  return Boolean(match && !match.playerEntryCompleted && match.playerLineupStatus === "bench"
    && match.offenseTeam === getHighSchoolPlayerTeamSide(match)
    && match.inning >= Math.max(1, Number(match.playerEntryWindowInning) || 1)
    && match.outs < 3);
}

function enterHighSchoolMatchPlayer(match) {
  assertHighSchoolMatchCapabilityAdmission(player);
  if (!shouldEnterHighSchoolMatchPlayer(match)) return false;
  const entryTruth = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
  const insertion = insertPlayerIntoHighSchoolMatchLineup(match);
  if (!insertion) return false;
  match.playerLineupStatus = "substitute";
  match.playerEntryCompleted = true;
  match.playerFieldingAssignment = match.gameExposureState?.opportunitySnapshot?.assignedPosition || match.developmentPositionOverride || match.position;
  match.currentFieldingPosition = match.playerFieldingAssignment;
  match.currentBatter = "player";
  const plannedAppearance = match.gameExposureState?.plannedUsage?.appearanceType || "lateGameAppearance";
  const entryLabel = !match.gameExposureState ? "叫你代打"
    : plannedAppearance === "defensiveSubstitution" ? "準備接替守備，並先從這個打席進入比賽"
    : plannedAppearance === "pinchHit" ? "叫你代打" : "叫你進入比賽";
  match.matchEntryHistory = `${match.inning}局${match.half}${match.outs}出局時，教練${entryLabel}；進場比分與壘況沿用當下比賽。`;
  match.currentAssignment = `${formatHighSchoolMatchRunners(match.runners)}、${match.outs} 出局；你從板凳進入第 ${insertion.slot + 1} 棒。`;
  setHighSchoolCoachTacticalDirection(match);
  const event = recordHighSchoolMatchSimulationEvent(match, {
    type: "playerEntry", inning: entryTruth.inning, half: entryTruth.half,
    lineupSlot: insertion.slot, replacedPlayerId: insertion.replaced?.id || "", plannedAppearanceType: plannedAppearance,
    assignment: match.currentAssignment, outs: entryTruth.outs, scores: entryTruth.scores, runners: entryTruth.runners
  });
  recordHighSchoolMatchOpportunityCheckpoint("player-entry", match, {
    lineupSlot: insertion.slot,
    entry: { inning: entryTruth.inning, half: entryTruth.half, outs: entryTruth.outs, scores: entryTruth.scores, runners: entryTruth.runners }
  });
  return event;
}

function insertPlayerIntoHighSchoolMatchLineup(match) {
  const lineup = match.rosters?.[getHighSchoolPlayerTeamSide(match)]?.lineup;
  const bench = match.rosters?.[getHighSchoolPlayerTeamSide(match)]?.bench;
  if (typeof TeamRosterFoundation !== "undefined") TeamRosterFoundation.assertActiveDefense(match.rosters?.[getHighSchoolPlayerTeamSide(match)]);
  if (!Array.isArray(lineup)) return false;
  const existingSlot = lineup.findIndex(item => item.id === "player");
  if (existingSlot >= 0) {
    match.playerLineupSlot = existingSlot;
    return false;
  }
  const slot = Math.max(0, Math.min(8, Number(match.battingOrderIndex?.[getHighSchoolPlayerTeamSide(match)]) || 0));
  const replaced = lineup[slot];
  const assignedPosition = match.gameExposureState?.opportunitySnapshot?.assignedPosition
    || match.developmentPositionOverride || match.playerFieldingAssignment || match.position;
  const incumbent = getCurrentHighSchoolMatchDefender(match, getHighSchoolPlayerTeamSide(match), assignedPosition);
  if (!incumbent) throw new Error("Active defense integrity failed: missing substitution incumbent");
  if (incumbent !== replaced) return false;
  const benchPlayer = (bench || []).find(item => item.id === "player");
  if (!benchPlayer) throw new Error("Active defense integrity failed: incoming player not on bench");
  const incoming = { ...benchPlayer, id: "player", name: player.name || "你",
    position: replaced.position, defensivePosition: replaced.defensivePosition,
    bats: player.bats, throws: player.throws, age: player.age, source: "canonical-player" };
  const nextRoster = { ...match.rosters[getHighSchoolPlayerTeamSide(match)], lineup: lineup.map((actor, index) => index === slot ? incoming : actor),
    bench: [...(bench || []).filter(item => item.id !== "player"), replaced] };
  if (typeof TeamRosterFoundation !== "undefined") TeamRosterFoundation.assertActiveDefense(nextRoster);
  match.rosters[getHighSchoolPlayerTeamSide(match)] = nextRoster;
  match.playerLineupSlot = slot;
  return { slot, replaced };
}

function advanceHighSchoolMatchPlaybackStep(match = player.highSchoolMatch) {
  if (!match || match.completed) return false;
  if (match.activeSituation?.type === "groundBallDefensiveDecision" && match.activeSituation.lifecycleState === "resolved") {
    return resumeResolvedHighSchoolGroundBallSettlement(match);
  }
  if (!isHighSchoolMatchPlaybackPhase(match)) return false;
  const activeSituation = typeof MatchSituationLifecycle !== "undefined"
    ? MatchSituationLifecycle.normalizeSituation(match.activeSituation) : null;
  if (activeSituation && !MatchSituationLifecycle.canResumeSimulation(activeSituation)) return "decision";
  const pendingEvent = advanceHighSchoolPresentationCursor(match);
  if (pendingEvent) return getHighSchoolPlaybackResultForPresentedEvent(pendingEvent);
  if (match.pendingGameSettlement) {
    finishHighSchoolMatchBySimulation(match);
    return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match)) || "gameEnd";
  }
  if (needsHighSchoolScoreboardReveal(match)) {
    match.scoreboardRevealHalfIndex = getHighSchoolScoreboardRevealHalfIndex(match) + 1;
    const visibleHalf = getHighSchoolHalfInningFromIndex(match.scoreboardRevealHalfIndex);
    match.passage = `${visibleHalf.inning}局${visibleHalf.half}已在記分板上展開；比分只顯示目前播放到的進度。`;
    return "scoreboardReveal";
  }
  const target = match.simulationPhase === "full_match_flow" ? "firstOffense"
    : match.simulationPhase === "moment_1_resolved" ? "defense"
    : match.simulationPhase === "moment_2_resolved" ? "finalOffense" : "finish";
  const startIndex = getHighSchoolPresentedEventCursor(match);
  const scoresBefore = { ...match.scores };
  const playerStartedOnBase = match.playerRunnerLocation >= 0;
  const startingInning = match.inning;
  const startingHalf = match.half;

  if (isHighSchoolMatchWalkOff(match)) {
    recordHighSchoolMatchSimulationEvent(match, {
      type: "walkOff", inning: match.inning, half: match.half, scores: match.scores
    });
    match.pendingGameSettlement = "walkOff";
    advanceHighSchoolPresentationCursor(match);
    return "walkOff";
  }

  if (match.outs >= 3 && shouldEndHighSchoolMatchAfterHalf(match, startingInning, startingHalf)) {
    finishHighSchoolMatchAtCompletedHalf(match, startingInning, startingHalf);
    match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
    return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
  }
  if (match.outs >= 3) {
    endHighSchoolMatchHalfInning(match);
    const runs = (match.scores.home - scoresBefore.home) + (match.scores.away - scoresBefore.away);
    match.currentAssignment = `${startingInning}局${startingHalf}已結束；接著進入${match.inning}局${match.half}。`;
    match.passage = `${startingInning}局${startingHalf}完成，這個半局產生 ${runs} 分。記分板保留先前所有局數，下一個半局接著開始。`;
    return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
  }

  if (shouldEnterHighSchoolMatchPlayer(match)) {
    enterHighSchoolMatchPlayer(match);
    match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
    return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
  }

  const batter = getHighSchoolMatchLineupBatter(match, match.offenseTeam);
  if (batter?.id === "player") {
    const agencyChoices = buildOffensiveDecisionChoices(match).filter(choice => isOffensiveDecisionChoiceLegal(choice, match));
    const agencyClassification = classifyHighSchoolOffensiveOpportunity(match, agencyChoices);
    const agencyDensity = evaluateHighSchoolOffensiveDecisionDensity(match, agencyClassification);
    const agency = evaluateHighSchoolOffensivePlayerAgency(match, agencyClassification);
    if (agency.lateGamePlayerAgency) {
      const routeTarget = target === "firstOffense" && shouldCreateHighSchoolFirstOffensiveMoment(match) ? "firstOffense"
        : target === "finalOffense" && shouldReachHighSchoolFinalOffensiveMoment(match) ? "finalOffense" : "classified";
      prepareHighSchoolOffensiveAgencyChoice(match, agencyClassification, agencyDensity, { routeTarget });
      match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
      return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
    }
  }
  const defensiveOpportunity = beginHighSchoolMatchDefensiveOpportunity(match, batter, target);
  if (target === "firstOffense" && shouldCreateHighSchoolFirstOffensiveMoment(match)) {
    prepareHighSchoolFirstOffensiveMomentFromSimulation(match);
    match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
    return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
  }
  const activeFieldingPosition = match.developmentPositionOverride || match.playerFieldingAssignment || match.currentFieldingPosition || match.position;
  const defensiveOpportunityPhase = target === "defense" || activeFieldingPosition === "一壘手"
    || (["二壘手", "游擊手", "三壘手", "一壘手"].includes(activeFieldingPosition) && ["finalOffense", "finish"].includes(target));
  const defensiveResponsibilityReached = defensiveOpportunityPhase && shouldReachHighSchoolDefensiveMoment(match);
  if (defensiveOpportunity) defensiveOpportunity.responsibilityCheck = defensiveResponsibilityReached;
  if (defensiveResponsibilityReached) {
    const defensiveEvent = prepareHighSchoolDefensiveMomentFromSimulation(match, { opportunityTraceId: defensiveOpportunity?.opportunityId || "",
      incomingContinuation: createHighSchoolIncomingContinuationAdmission(match, batter) });
    if (defensiveEvent) {
      match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
      return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
    }
  }
  if (target === "finalOffense" && shouldReachHighSchoolFinalOffensiveMoment(match)) {
    prepareHighSchoolFinalOffensiveMomentFromSimulation(match);
    match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
    return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
  }
  let offensiveRoutineOpportunity = null;
  if (batter?.id === "player") {
    const choices = buildOffensiveDecisionChoices(match).filter(choice => isOffensiveDecisionChoiceLegal(choice, match));
    const classification = classifyHighSchoolOffensiveOpportunity(match, choices);
    const density = evaluateHighSchoolOffensiveDecisionDensity(match, classification);
    if (density.allowed) {
      applyHighSchoolOffensiveDecisionDensity(match, classification, density, true);
      prepareHighSchoolMeaningfulOffensiveMomentFromSimulation(match, classification, density);
      match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
      return getHighSchoolPlaybackResultForPresentedEvent(advanceHighSchoolPresentationCursor(match));
    }
    applyHighSchoolOffensiveDecisionDensity(match, classification, density, false);
    offensiveRoutineOpportunity = recordHighSchoolMatchOffensiveOpportunity(match, "routine", choices, classification, density);
  }
  const simulationLogLengthBeforePA = match.simulationLog.length;
  const result = batter ? resolveSimulatedHighSchoolPlateAppearance(match, null, { allowPlayer: batter.id === "player" }) : false;
  if (!result) return false;
  const plateAppearanceEvent = match.simulationLog.slice(simulationLogLengthBeforePA).find(event => event.type === "plateAppearance") || null;
  finalizeHighSchoolMatchDefensiveOpportunity(match, defensiveOpportunity, plateAppearanceEvent, plateAppearanceEvent?.result || "ordinary-pa");
  if (offensiveRoutineOpportunity) {
    offensiveRoutineOpportunity.result = plateAppearanceEvent?.result || "";
    offensiveRoutineOpportunity.simulationLogIndex = Number.isFinite(Number(plateAppearanceEvent?.sequence)) ? Number(plateAppearanceEvent.sequence) : match.simulationLog.length - 1;
  }
  if (isHighSchoolMatchWalkOff(match)) {
    recordHighSchoolMatchSimulationEvent(match, {
      type: "walkOff", inning: match.inning, half: match.half, scores: match.scores
    });
    match.pendingGameSettlement = "walkOff";
  }
  const event = advanceHighSchoolPresentationCursor(match);
  match.passage = summarizeHighSchoolSimulationSegment(match, startIndex, scoresBefore, playerStartedOnBase);
  return getHighSchoolPlaybackResultForPresentedEvent(event);
}

function shouldReachHighSchoolDefensiveMoment(match) {
  if (!isHighSchoolMatchPlayerActive(match) || match.offenseTeam !== getHighSchoolOpponentTeamSide(match) || match.outs >= 3) return false;
  // Player 1B participates in the existing PA stream as a receiver. Presentation
  // density cannot suppress the physical stage after the first routine in a half.
  if (typeof TeamRosterFoundation !== "undefined" && TeamRosterFoundation.getCurrentDefender(match.rosters?.[match.defenseTeam], "1B")?.id === "player") return true;
  const force = getHighSchoolDefensiveForceState(match);
  const scoreDifference = Math.abs(getHighSchoolPlayerScoreDifference(match));
  const naturalPressure = match.outs < 2 && (force.doublePlayEligible || (force.third && scoreDifference <= 1));
  const fallbackInning = Math.max(2, (Number(match.playerEntryWindowInning) || 1) + 1);
  const routineAlreadyShownThisHalf = (match.simulationLog || []).some(event => event.type === "playerRoutinePlay"
    && event.inning === match.inning && event.half === match.half);
  return naturalPressure || (match.inning >= fallbackInning && !routineAlreadyShownThisHalf);
}

function getHighSchoolDefensiveOpportunity(match, physicalTruth) {
  if (typeof DefensiveOpportunityFoundation === "undefined") return null;
  const prior = match?.groundBallInPlayState;
  const samePhysical = prior?.physicalTruth?.identity === physicalTruth?.identity;
  const historical = samePhysical && (prior?.defensiveOpportunity || (prior?.defensiveAccess?.reachResolution
    ? { topologyVersion: "regulation-coarse-zones-v1" } : null));
  const responsibility = DefensiveOpportunityFoundation.deriveGroundResponsibility?.(physicalTruth,
    DefensiveOpportunityFoundation.FIRST_BASE_GROUND_TOPOLOGY_VERSION);
  // The classifier is shared by player and NPC assignments. Unchanged SS/2B
  // lanes keep their existing execution identities; saved lanes retain their version.
  const topologyVersion = historical ? historical.topologyVersion
    : responsibility?.primaryPosition === "1B" ? DefensiveOpportunityFoundation.FIRST_BASE_GROUND_TOPOLOGY_VERSION
      : responsibility?.primaryPosition === "3B" ? DefensiveOpportunityFoundation.GROUND_TOPOLOGY_VERSION : undefined;
  return DefensiveOpportunityFoundation.resolveDefensiveOpportunity({
    physicalTruth, activeRoster: match?.rosters?.[match.defenseTeam], topologyVersion
  });
}

function getHighSchoolPhysicalDefensePlayerContext(match, physicalTruth, defenderContext, options = {}) {
  const opportunity = getHighSchoolDefensiveOpportunity(match, physicalTruth);
  if (!opportunity) return defenderContext; // Pre-foundation isolated harness compatibility.
  if (opportunity.bindingStatus === "invalid") throw new Error("Active defense integrity failed: defensive opportunity binding");
  const ownsGroundSlice = opportunity.supported && opportunity.primaryDefenderId === "player"
    && (opportunity.primaryPosition === "2B" || (["SS", "3B", "1B"].includes(opportunity.primaryPosition) && physicalTruth.ballType === "groundBall"));
  const firstBase = TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], "1B");
  const continuation = options.incomingContinuation;
  const liveContinuation = continuation?.version === "incoming-continuation-admission-v1"
    && continuation.matchId === match.id && continuation.batterId === match.currentBatter
    && continuation.inning === match.inning && continuation.half === match.half
    && continuation.offenseTeam === match.offenseTeam && continuation.defenseTeam === match.defenseTeam
    && continuation.outs === match.outs && JSON.stringify(continuation.runners) === JSON.stringify(match.runners);
  const receivesGroundSlice = firstBase?.id === "player" && physicalTruth.ballType === "groundBall"
    && liveContinuation && opportunity.supported && ["SS", "2B", "3B"].includes(opportunity.primaryPosition);
  const npc = receivesGroundSlice ? TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], opportunity.primaryPosition) : null;
  const acquisition = npc ? getDefensiveSimulationCapability(npc, npc.position, match) : defenderContext;
  return { ...defenderContext, ...acquisition, playerPosition: ownsGroundSlice || receivesGroundSlice ? TeamRosterFoundation.POSITION_LABELS[opportunity.primaryPosition] : "",
    defensiveOpportunity: opportunity,
    ...(ownsGroundSlice || receivesGroundSlice ? { reachAccess: getHighSchoolReachAccess(match, physicalTruth, opportunity, acquisition) } : {}) };
}

function getHighSchoolReachAccess(match, physicalTruth, opportunity, defenderContext) {
  if (typeof DefensiveReachSecureFoundation === "undefined" || !opportunity?.supported) return null;
  const actor = TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], opportunity.primaryPosition);
  const source = actor.id === "player" ? player : actor;
  const adapted = getDefensiveSimulationCapability(source, opportunity.primaryPosition, match);
  const capabilities = { defenderId: actor.id,
    reaction: defenderContext.reaction ?? adapted.reaction,
    range: defenderContext.range ?? adapted.range,
    mobility: getOffensiveSimulationCapability(source).speed,
    fielding: defenderContext.fielding ?? defenderContext.catching ?? adapted.fielding,
    catching: defenderContext.catching ?? defenderContext.fielding ?? adapted.fielding };
  const reach = DefensiveReachSecureFoundation.resolveReach({ physicalTruth, opportunity,
    activeRoster: match.rosters[match.defenseTeam], capabilities, roll: defenderContext.reachRoll });
  return { ...DefensiveReachSecureFoundation.projectAccess(reach), secureCapabilities: capabilities };
}

function ensureHighSchoolOrdinaryGroundBallInPlayHandoff(match, options = {}) {
  if (!match || typeof BattedBallGroundDefense === "undefined" || typeof OffensivePlateApproach === "undefined") return null;
  if (match.offensiveTacticalActionState?.selectedTacticalAction !== "standardAttack") return null;
  const playerPosition = match.developmentPositionOverride || getHighSchoolInfieldAssignmentPosition(match, player);
  const batter = getHighSchoolMatchSimulationEntity(match, match.currentBatter);
  const paIdentity = `${createHighSchoolOffensiveTacticalIdentity(match)}|ordinary-contact`;
  const existing = BattedBallGroundDefense.normalizeHandoff(match.groundBallInPlayState);
  const existingLineDrive = typeof BattedBallLineDriveDefense !== "undefined"
    ? BattedBallLineDriveDefense.normalizeCatchState(match.lineDriveCatchState) : null;
  const existingFlyBall = typeof BattedBallFlyBallDefense !== "undefined"
    ? BattedBallFlyBallDefense.normalizeFlyBallCatchState(match.flyBallCatchState) : null;
  if (existing?.identity === `${paIdentity}|ground-defense`) {
    validateHighSchoolReceiverSourceMetadata(match);
    if (existing.supported && !existing.settlementApplied) assertHighSchoolGroundParticipant(match);
    match.groundBallInPlayState = existing;
    return existing;
  }
  if (existingLineDrive?.identity === `${paIdentity}|line-drive-catch`) {
    if (existingLineDrive.supported && !existingLineDrive.settlementApplied) assertHighSchoolDetailedResponsibility(match, existingLineDrive.physicalTruth, "2B", "player");
    match.lineDriveCatchState = existingLineDrive;
    return null;
  }
  if (existingFlyBall?.identity === `${paIdentity}|fly-ball-catch`) {
    if (existingFlyBall.supported && !existingFlyBall.settlementApplied) assertHighSchoolDetailedResponsibility(match, existingFlyBall.physicalTruth, existingFlyBall.defenderContext?.position, existingFlyBall.defenderContext?.defenderId);
    match.flyBallCatchState = existingFlyBall;
    return null;
  }
  const defender = {
    ...getDefensiveSimulationCapability(player, "內野手"),
    ...(options.situationOverrides?.playerCapabilities || {})
  };
  const physicalDefenderContext = physicalTruth => getHighSchoolPhysicalDefensePlayerContext(match, physicalTruth, {
    playerPosition, catching: defender.fielding, reaction: defender.reaction, range: defender.range
  }, options);
  const offense = getHighSchoolProvisionalOffensiveTacticalCapabilities(match);
  const initial = OffensivePlateApproach.createPlateAppearanceState({
    paIdentity,
    batterId: match.currentBatter,
    approach: "balancedAttack",
    context: { outs: match.outs, runners: match.runners.slice(), hasRunner: match.runners.some(Boolean) }
  });
  const fixture = options.ordinaryPlateAppearance || {};
  const pitch = fixture.pitch || { pitchLocationClass: "hitterPitch" };
  const pitchOptions = {
    recognitionRoll: fixture.recognitionRoll ?? 0,
    decisionRoll: fixture.decisionRoll ?? 0,
    contactRoll: fixture.contactRoll ?? 0,
    foulRoll: fixture.foulRoll ?? 1,
    physicalRolls: fixture.physicalRolls,
    outcomeRoll: fixture.outcomeRoll,
    physicalOutcomeResolver({ physicalTruth }) {
      const access = BattedBallGroundDefense.resolveGroundBallDefensiveAccess({
        physicalTruth,
        defenderContext: physicalDefenderContext(physicalTruth)
      });
      if (access.supported) return {
        result: "groundBallDefensePending",
        authority: "bbpB1PhysicalDefensePending",
        contactQuality: Number(physicalTruth.executionEvidence?.continuousContactScore) || 0,
        resolvedContact: null
      };
      if (typeof BattedBallLineDriveDefense !== "undefined") {
        const airborneContext = BattedBallLineDriveDefense.buildAirborneBallContext(physicalTruth);
        const catchAccess = airborneContext ? BattedBallLineDriveDefense.resolveCatchAccess({
          airborneContext,
          defenderContext: physicalDefenderContext(physicalTruth)
        }) : null;
        const catchWindow = catchAccess ? BattedBallLineDriveDefense.buildCatchTimingWindow({ airborneContext, defensiveAccess: catchAccess }) : null;
        if (catchAccess?.supported && catchWindow?.state !== "expired") return {
          result: "lineDriveCatchPending",
          authority: "bbpB2APhysicalCatchPending",
          contactQuality: Number(physicalTruth.executionEvidence?.continuousContactScore) || 0,
          resolvedContact: null
        };
      }
      if (typeof BattedBallFlyBallDefense !== "undefined") {
        const flyBallDefender = getHighSchoolFlyBallDefenderCatchContext(match, physicalTruth, options);
        const flyBallOpportunity = BattedBallFlyBallDefense.buildFlyBallCatchOpportunity({
          identity: `${paIdentity}|fly-ball-catch`, physicalTruth, runners: [], outs: match.outs,
          runnerEntities: [], defenderContext: flyBallDefender
        });
        if (flyBallOpportunity?.supported) return {
          result: "flyBallCatchPending",
          authority: "bbpB2B1PhysicalCatchPending",
          contactQuality: Number(physicalTruth.executionEvidence?.continuousContactScore) || 0,
          resolvedContact: null
        };
      }
      return null;
    }
  };
  const plateAppearanceState = OffensivePlateApproach.simulatePlateAppearance({
    state: initial,
    abilities: {
      observe: Number(offense.baseballIQ) || 5,
      baseballIQ: Number(offense.baseballIQ) || 5,
      ballSense: Number(offense.ballSense) || 5,
      batting: Number(offense.batting) || 5,
      power: Number(batter?.power) || Number(offense.batting) || 5,
      bats: batter?.bats || "R"
    },
    pitchSequence: [pitch],
    pitchOptions: [pitchOptions]
  });
  match.ordinaryDefensivePlateAppearanceState = JSON.parse(JSON.stringify(plateAppearanceState));
  const physicalTruth = plateAppearanceState.battedBallPhysicalTruth;
  const runnerEntities = match.runners.map((runnerId, index) => {
    if (!runnerId) return null;
    const entity = getHighSchoolMatchSimulationEntity(match, runnerId);
    return {
      runnerId,
      originBase: index + 1,
      speed: Number(entity?.speed) || 5,
      reaction: Number(entity?.reaction) || Number(entity?.defense) || 5,
      baseballIQ: Number(entity?.baseballIQ) || Number(entity?.decision) || 5
    };
  }).filter(Boolean);
  if (plateAppearanceState.result === "lineDriveCatchPending" && physicalTruth && typeof BattedBallLineDriveDefense !== "undefined") {
    match.groundBallInPlayState = null;
    match.flyBallCatchState = null;
    match.lineDriveCatchState = BattedBallLineDriveDefense.buildCatchOpportunity({
      identity: `${paIdentity}|line-drive-catch`,
      physicalTruth,
      runners: match.runners,
      outs: match.outs,
      runnerEntities,
      preContactRunnerStates: options.preContactRunnerStates || {},
      defenderContext: physicalDefenderContext(physicalTruth)
    });
    return null;
  }
  if (plateAppearanceState.result === "flyBallCatchPending" && physicalTruth && typeof BattedBallFlyBallDefense !== "undefined") {
    match.groundBallInPlayState = null;
    match.lineDriveCatchState = null;
    match.flyBallCatchState = BattedBallFlyBallDefense.buildFlyBallCatchOpportunity({
      identity: `${paIdentity}|fly-ball-catch`,
      physicalTruth,
      runners: match.runners,
      outs: match.outs,
      runnerEntities,
      preContactRunnerStates: options.preContactRunnerStates || {},
      defenderContext: getHighSchoolFlyBallDefenderCatchContext(match, physicalTruth, options)
    });
    return null;
  }
  if (plateAppearanceState.result !== "groundBallDefensePending" || !physicalTruth) {
    const ordinaryInfield = isInfieldDecisionFamilyPosition(match.developmentPositionOverride || match.playerFieldingAssignment || match.position);
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({
      version: BattedBallGroundDefense.VERSION,
      identity: `${paIdentity}|ground-defense`,
      sourceAuthority: "unsupportedOrdinaryContactLegacyFallback",
      physicalTruth: physicalTruth ? JSON.parse(JSON.stringify(physicalTruth)) : null,
      supported: false,
      ...(ordinaryInfield ? { fallbackAuthority: "existingOrdinaryPhysicalOutcome",
        defensiveOpportunity: physicalTruth ? getHighSchoolDefensiveOpportunity(match, physicalTruth) : null }
        : { fallbackAuthority: "existingSyntheticDefensiveContext" }),
      legacyFallbackResult: plateAppearanceState.result || ""
    });
    match.lineDriveCatchState = physicalTruth?.ballType === "lineDrive" && typeof BattedBallLineDriveDefense !== "undefined"
      ? BattedBallLineDriveDefense.buildCatchOpportunity({
        identity: `${paIdentity}|line-drive-catch`, physicalTruth, runners: match.runners, outs: match.outs,
        runnerEntities, preContactRunnerStates: options.preContactRunnerStates || {},
        defenderContext: physicalDefenderContext(physicalTruth)
      }) : null;
    match.flyBallCatchState = physicalTruth?.ballType === "flyBall" && typeof BattedBallFlyBallDefense !== "undefined"
      ? BattedBallFlyBallDefense.buildFlyBallCatchOpportunity({
        identity: `${paIdentity}|fly-ball-catch`, physicalTruth, runners: match.runners, outs: match.outs,
        runnerEntities, preContactRunnerStates: options.preContactRunnerStates || {},
        defenderContext: getHighSchoolFlyBallDefenderCatchContext(match, physicalTruth, options)
      }) : null;
    return match.groundBallInPlayState;
  }
  const forceState = BattedBallGroundDefense.deriveForceState({ runners: match.runners, outs: match.outs });
  match.lineDriveCatchState = null;
  match.flyBallCatchState = null;
  match.groundBallInPlayState = BattedBallGroundDefense.buildGroundBallDefensiveOpportunity({
    identity: `${paIdentity}|ground-defense`,
    physicalTruth,
    runners: match.runners,
    outs: match.outs,
    forceState,
    runnerEntities,
    batterRunner: { runnerId: match.currentBatter, speed: Number(batter?.speed) || 5 },
    preContactRunnerStates: options.preContactRunnerStates || {},
    defenderContext: physicalDefenderContext(physicalTruth)
  });
  const firstBaseContext = createHighSchoolFirstBaseContext(match, match.groundBallInPlayState, options);
  if (firstBaseContext) match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({
    ...match.groundBallInPlayState, defensiveOpportunity: getHighSchoolDefensiveOpportunity(match, physicalTruth), firstBaseContext });
  // Unique SOURCE-only admission owner. This runs before classification, lifecycle execution and the original sample.
  const sourceHandoff = match.groundBallInPlayState;
  const sourceApi = getHighSchoolReceiverSourceAdapter(match);
  const sourceOpportunity = sourceApi ? getHighSchoolDefensiveOpportunity(match, physicalTruth) : null;
  const sourceRoster = match.rosters?.[match.defenseTeam];
  const sourceSs = sourceApi && sourceRoster ? TeamRosterFoundation.getCurrentDefender(sourceRoster, "SS") : null;
  const sourceFirst = sourceApi && sourceRoster ? TeamRosterFoundation.getCurrentDefender(sourceRoster, "1B") : null;
  if (sourceApi && sourceHandoff.supported && !firstBaseContext
    && sourceHandoff.defensiveAccess?.playerPosition === "游擊手" && sourceOpportunity?.primaryPosition === "SS"
    && sourceSs?.id === "player" && sourceFirst?.id && sourceFirst.id !== "player"
    && match.outs >= 0 && match.outs < 3 && match.runners.every(r => !r)
    && sourceHandoff.runnerRealization?.batterRunner?.runnerId === match.currentBatter) {
    const source = sourceApi.createSnapshot({ beforeExecution: true,
      physical: { version: sourceApi.versions.physical, matchId: match.id, plateAppearanceId: plateAppearanceState.paIdentity,
        contactId: physicalTruth.identity, physicalIdentity: physicalTruth.identity, playId: sourceHandoff.identity },
      original: { outs: match.outs, bases: match.runners.slice(), defenseTeam: match.defenseTeam,
        thrower: { actorId: sourceSs.id, position: "SS", role: "player" }, receiver: { actorId: sourceFirst.id, position: "1B", role: "npc" },
        batterRunner: match.currentBatter, firstBaseObligation: { runnerId: match.currentBatter, base: "first", forceReason: "batterRunnerRequiredToFirst" },
        topologyVersion: sourceOpportunity.topologyVersion },
      capabilitySource: { adapterVersion: sourceApi.versions.adapter,
        thrower: JSON.parse(JSON.stringify(sourceHandoff.defensiveAccess.secureCapabilities)),
        receiver: Object.fromEntries(["defense", "speed", "arm", "contact"].map(k => [k, Number.isFinite(sourceFirst[k]) ? sourceFirst[k] : null])),
        reference: sourceHandoff.defensiveAccess.reachResolution.identity } });
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...sourceHandoff, receiverSourceFormatVersion: source.formatVersion,
      receiverSourceSnapshot: source.snapshot, receiverSourcePin: source.pin });
    match.receiverSourceFormatVersion = source.formatVersion;
    match.receiverSourceAdmission = source;
    validateHighSchoolReceiverSourceMetadata(match);
  }
  return match.groundBallInPlayState;
}

function prepareHighSchoolDefensiveMomentFromSimulation(match, options = {}) {
  if (match.activeSituation
    && !MatchSituationLifecycle.canResumeSimulation(match.activeSituation)) return null;
  const opportunity = findHighSchoolMatchOpportunity(match, options.opportunityTraceId);
  const densityState = ensureHighSchoolMatchDecisionDensityState(match);
  const flowState = {
    momentIndex: match.momentIndex,
    currentMomentId: match.currentMomentId,
    simulationPhase: match.simulationPhase,
    currentDomain: match.currentDomain,
    currentAssignment: match.currentAssignment
  };
  const primaryDefensiveDecision = flowState.simulationPhase === "moment_1_resolved"
    && (densityState?.defensiveMeaningfulDecisionCount || 0) === 0;
  match.pendingDefensiveResumeState = {
    simulationPhase: primaryDefensiveDecision ? "moment_2_resolved" : flowState.simulationPhase,
    momentIndex: primaryDefensiveDecision ? 1 : flowState.momentIndex,
    currentMomentId: primaryDefensiveDecision ? highSchoolYearOneMomentIds[1] : flowState.currentMomentId,
    currentDomain: "flow",
    currentAssignment: flowState.currentAssignment
  };
  match.currentBatter = getHighSchoolMatchLineupBatter(match, match.offenseTeam)?.id || "";
  match.momentIndex = 1;
  match.currentMomentId = primaryDefensiveDecision ? highSchoolYearOneMomentIds[1]
    : `hs_y1_match_defense_${(densityState?.defensiveMeaningfulDecisionCount || 0) + 1}`;
  match.currentDomain = "defense";
  const offensiveTacticalState = prepareHighSchoolOffensiveTacticalAction(match, options);
  if (offensiveTacticalState) {
    advanceHighSchoolOffensiveTacticalReveal(match, options.tacticalRevealPhase || "lateReveal");
  } else {
    match.opponentTacticalTruth = {
      code: match.previousMomentDecision === "zone" ? "hitAndRun" : match.previousMomentDecision === "attack" ? "earlyBreak" : "shortSwing",
      targetRunnerId: match.runners[1] || match.runners[0] || match.runners[2] || ""
    };
  }
  const productionBunt = offensiveTacticalState && typeof OffensiveBuntExecution !== "undefined"
    ? resolveHighSchoolProductionBuntPitch(match, {
      ...(options.buntPitchOptions || {}),
      initialCount: options.buntInitialCount
    }) : null;
  if (productionBunt?.event) {
    match.momentIndex = flowState.momentIndex;
    match.currentMomentId = flowState.currentMomentId;
    match.simulationPhase = flowState.simulationPhase;
    match.currentDomain = flowState.currentDomain;
    match.currentAssignment = flowState.currentAssignment;
    match.pendingDefensiveResumeState = null;
    setHighSchoolCoachTacticalDirection(match);
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, productionBunt.event, productionBunt.status);
    return productionBunt.event;
  }
  const buntHandoff = productionBunt?.shouldBuildDefense ? ensureHighSchoolBuntBallInPlayHandoff(match) : null;
  const groundBallHandoff = !productionBunt && offensiveTacticalState?.selectedTacticalAction === "standardAttack"
    ? ensureHighSchoolOrdinaryGroundBallInPlayHandoff(match, options) : null;
  // Only this plate appearance's handoff may own a ground-ball lifecycle or apply guard.
  // A prior completed grounder must not suppress a later routine defensive settlement.
  match.groundBallInPlayState = groundBallHandoff;
  if (buntHandoff && !buntHandoff.supported) {
    if (buntHandoff.fallbackPresented !== true) {
      const fallbackText = buntHandoff.ballContext.downstreamSupport === "unsupportedPopBuntFallback"
        ? "短打形成小飛球，壘上跑者回頭確認球是否落地；本階段不預判接殺或離壘出局。"
        : `短打落在${buntHandoff.ballContext.physicalTruth.placement === "thirdBaseSide" ? "三壘側" : buntHandoff.ballContext.physicalTruth.placement === "firstBaseSide" ? "一壘側" : "投手附近"}；此守備位置尚未納入二壘手垂直切片。`;
      match.buntBallInPlayState = Object.freeze({ ...JSON.parse(JSON.stringify(buntHandoff)), fallbackPresented: true });
      const fallbackEvent = recordHighSchoolMatchSimulationEvent(match, {
        type: "buntDefensiveFallback", presentationImportance: "attention", inning: match.inning, half: match.half,
        assignment: fallbackText, presentation: fallbackText, outs: match.outs, scores: match.scores, runners: match.runners
      });
      match.momentIndex = flowState.momentIndex;
      match.currentMomentId = flowState.currentMomentId;
      match.simulationPhase = flowState.simulationPhase;
      match.currentDomain = flowState.currentDomain;
      match.currentAssignment = flowState.currentAssignment;
      match.pendingDefensiveResumeState = null;
      finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, fallbackEvent, "unsupported-bunt-defense");
      return fallbackEvent;
    }
    return null;
  }
  const lineDriveCatchOpportunity = typeof BattedBallLineDriveDefense !== "undefined"
    ? BattedBallLineDriveDefense.normalizeCatchState(match.lineDriveCatchState) : null;
  if (!productionBunt && lineDriveCatchOpportunity?.supported) {
    resolveHighSchoolLineDriveCatchOpportunity(match, options);
    const catchEvent = applyHighSchoolLineDriveCatchResolution(match);
    restoreHighSchoolMatchAfterDefensiveDecision(match, flowState.simulationPhase);
    match.currentDomain = "flow";
    setHighSchoolCoachTacticalDirection(match);
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, catchEvent, "routine-line-drive-catch");
    return catchEvent;
  }
  const flyBallCatchOpportunity = typeof BattedBallFlyBallDefense !== "undefined"
    ? BattedBallFlyBallDefense.normalizeFlyBallCatchState(match.flyBallCatchState) : null;
  if (!productionBunt && flyBallCatchOpportunity?.supported) {
    resolveHighSchoolFlyBallCatchOpportunity(match, options);
    const catchEvent = applyHighSchoolFlyBallCatchResolution(match);
    const tagUpSituation = createHighSchoolRunnerTagUpSituation(match);
    if (tagUpSituation?.admission?.admittedToPlayer && tagUpSituation.lifecycleState === "presented") {
      setHighSchoolCoachTacticalDirection(match);
      finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, catchEvent, "tag-up-decision-created");
      return catchEvent;
    }
    restoreHighSchoolMatchAfterDefensiveDecision(match, flowState.simulationPhase);
    match.currentDomain = "flow";
    setHighSchoolCoachTacticalDirection(match);
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, catchEvent, "routine-fly-ball-catch");
    return catchEvent;
  }
  if (groundBallHandoff && !groundBallHandoff.supported
    && isInfieldDecisionFamilyPosition(match.developmentPositionOverride || match.playerFieldingAssignment || match.position)) {
    // Preserve this PA's physical source for every assignment. Unsupported contact
    // cannot acquire a synthetic player primary merely by entering the infield family.
    const result = groundBallHandoff.legacyFallbackResult;
    const before = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
    const facts = applyHighSchoolSimulatedPlateAppearance(match, result, match.currentBatter, match.offenseTeam);
    const after = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
    const event = recordHighSchoolRoutinePlateAppearance(match, match.currentBatter, result, before, after,
      Math.max(0, after.scores[match.offenseTeam] - before.scores[match.offenseTeam]), {
        ...facts, physicalTruth: groundBallHandoff.physicalTruth, defensiveOpportunity: groundBallHandoff.defensiveOpportunity,
        outcomeAuthority: "existingOrdinaryPhysicalOutcome",
        eventClassification: "ordinaryPlay" });
    advanceHighSchoolMatchBattingOrder(match, match.offenseTeam);
    match.ordinaryDefensivePlateAppearanceState = OffensivePlateApproach.markResultApplied(match.ordinaryDefensivePlateAppearanceState);
    Object.assign(match, { momentIndex: flowState.momentIndex, currentMomentId: flowState.currentMomentId,
      simulationPhase: flowState.simulationPhase, currentDomain: flowState.currentDomain, currentAssignment: flowState.currentAssignment,
      pendingDefensiveResumeState: null, defensiveSituation: {}, positionDecisionFamily: "",
      playerEventClassification: "ordinaryPlay", decisionGate: null, decisionTension: "none" });
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...groundBallHandoff, settlementApplied: true });
    assertHighSchoolMatchStateIntegrity(match, "ordinary-outside-player-physical-scope");
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, event, "outside-player-physical-scope");
    return event;
  }
  if (buntHandoff) match.ballContext = JSON.parse(JSON.stringify(buntHandoff.ballContext));
  else if (groundBallHandoff?.supported) match.ballContext = JSON.parse(JSON.stringify(groundBallHandoff.ballContext));
  else setHighSchoolDefensiveBallContext(match, options.ballContextType || "");
  match.currentAssignment = getHighSchoolDefensiveSituationText(match);
  const priorTier = match.completedMoments[0]?.tier;
  match.coachInstruction = priorTier === "strong"
    ? "前一段執行已建立信任；現在先讀出局數，再決定是否挑戰額外出局。"
    : priorTier === "mixed"
      ? "先把最穩定的守備出局處理乾淨，不讓壘況繼續擴大。"
      : "前一段結果不影響你的守備資格；這一球只看補位與最短合法出局。";
  if (isInfieldDecisionFamilyPosition(match.developmentPositionOverride || match.position)) {
    match.defensiveSituation = {};
    const buntOverrides = getHighSchoolBuntDefensiveSituationOverrides(buntHandoff);
    const groundBallOverrides = getHighSchoolGroundBallDefensiveSituationOverrides(groundBallHandoff);
    const physicalOverrides = buntOverrides || groundBallOverrides;
    buildInfieldMeaningfulMoment(match, player, physicalOverrides
      ? { ...(options.situationOverrides || {}), ...physicalOverrides }
      : options.situationOverrides || {});
    match.currentAssignment = getHighSchoolDefensiveSituationText(match);
  } else {
    match.positionDecisionFamily = "";
    match.currentFieldingPosition = "";
    match.defensiveSituation = {};
  }
  match.opponentAdjustment = "跑者與打者的準備動作出現變化；只呈現你在場上能看見的線索。";
  const legalChoices = getHighSchoolDefensiveMomentChoices(match);
  const classification = match.defensiveSituation?.familyId === "infield"
    ? classifyHighSchoolMatchDefensiveOpportunity(match, match.defensiveSituation, legalChoices, true)
    : Object.freeze({ eventClassification: "playerMeaningfulDecision", decisionTension: "meaningful", gate: null });
  match.playerEventClassification = classification.eventClassification;
  match.decisionTension = classification.decisionTension;
  match.decisionGate = classification.gate ? JSON.parse(JSON.stringify(classification.gate)) : null;
  applyHighSchoolMatchDefensiveDecisionDensity(match, classification.density, classification.eventClassification === "playerMeaningfulDecision");
  updateHighSchoolMatchDefensiveOpportunityFromSituation(match, opportunity, match.defensiveSituation, legalChoices, classification);
  setHighSchoolCoachTacticalDirection(match);
  createGroundBallMatchSituation(match, legalChoices, classification, opportunity);
  if (classification.eventClassification === "playerRoutinePlay") {
    beginAutomaticGroundBallSituationExecution(match);
    const resolution = resolveRoutineDefensivePlay(match, match.defensiveSituation, options.randomSource ?? null, {
      densitySuppressed: classification.density?.meaningfulCandidate === true && classification.density?.allowed === false
    });
    if (!resolution) {
      if (typeof MatchSituationLifecycle !== "undefined"
        && match.activeSituation?.type === MatchSituationLifecycle.TYPES.groundBallDefensiveDecision) {
        abandonActiveMatchSituation(match, "noRoutineResolution");
      }
      match.momentIndex = flowState.momentIndex;
      match.currentMomentId = flowState.currentMomentId;
      match.simulationPhase = flowState.simulationPhase;
      match.currentDomain = flowState.currentDomain;
      match.currentAssignment = flowState.currentAssignment;
      match.pendingDefensiveResumeState = null;
      setHighSchoolCoachTacticalDirection(match);
      finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, null, "no-routine-resolution");
      return null;
    }
    recordGroundBallSituationResolution(match, resolution);
    const event = applyRoutineDefensiveResolutionToHighSchoolMatch(match, resolution);
    restoreHighSchoolMatchAfterDefensiveDecision(match, flowState.simulationPhase);
    match.currentDomain = "flow";
    setHighSchoolCoachTacticalDirection(match);
    finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, event, "routine");
    return event;
  }
  match.simulationPhase = "moment_2_ready";
  const event = recordHighSchoolMatchSimulationEvent(match, {
    type: "meaningfulMomentReached", eventClassification: "playerMeaningfulDecision", decisionTension: classification.decisionTension, inning: match.inning, half: match.half,
    momentId: match.currentMomentId, domain: match.currentDomain, assignment: match.currentAssignment,
    outs: match.outs, scores: match.scores, runners: match.runners
  });
  finalizeHighSchoolMatchDefensiveOpportunity(match, opportunity, event, "decision-created");
  return event;
}

function classifyHighSchoolMatchDefensiveOpportunity(match, situation, legalChoices = [], playerInvolved = true) {
  const classification = classifyPositionFamilyPlay(situation, legalChoices, playerInvolved);
  const density = evaluateHighSchoolMatchDefensiveDecisionDensity(match, situation, legalChoices, classification);
  if (classification.eventClassification !== "playerMeaningfulDecision" || density.allowed) {
    return Object.freeze({ ...classification, density });
  }
  return Object.freeze({
    eventClassification: "playerRoutinePlay",
    decisionTension: "low",
    gate: classification.gate,
    density
  });
}

function createGroundBallMatchSituation(match, legalChoices, classification, opportunity = null) {
  validateHighSchoolReceiverSourceMetadata(match);
  if (!match || typeof MatchSituationLifecycle === "undefined" || !match.groundBallInPlayState?.supported
    || match.defensiveSituation?.familyId !== "infield") return null;
  const handoff = match.groundBallInPlayState;
  assertHighSchoolGroundParticipant(match);
  const situationId = MatchSituationLifecycle.createSituationId({
    gameId: match.id,
    inning: match.inning,
    half: match.half,
    paIdentity: handoff.identity,
    simulationPoint: opportunity?.opportunityId || match.currentMomentId || match.simulationCursor,
    type: MatchSituationLifecycle.TYPES.groundBallDefensiveDecision
  });
  const existing = MatchSituationLifecycle.normalizeSituation(match.activeSituation);
  if (existing?.situationId === situationId) {
    match.activeSituation = existing;
    return existing;
  }
  if (existing && !MatchSituationLifecycle.canResumeSimulation(existing)) return existing;
  const presentationText = getHighSchoolDefensiveSituationText(match);
  let situation = MatchSituationLifecycle.createSituation({
    situationId,
    type: MatchSituationLifecycle.TYPES.groundBallDefensiveDecision,
    actor: {
      id: "player",
      role: match.defensiveSituation.responsibility?.playerRole || "",
      position: match.defensiveSituation.playerPosition || ""
    },
    sourceAuthority: "BattedBallPhysicalTruth+GroundBallRunnerRealization+InfieldRouteAvailability",
    sourcePhysicalStateRef: handoff.identity,
    createdAt: {
      inning: match.inning,
      half: match.half,
      outs: match.outs,
      score: { ...match.scores },
      bases: match.runners.slice(0, 3),
      paIdentity: handoff.identity,
      simulationPoint: opportunity?.opportunityId || match.currentMomentId || match.simulationCursor
    },
    contextSnapshot: {
      familyId: "infield",
      playerPosition: match.defensiveSituation.playerPosition,
      ...(handoff.firstBaseContext ? { firstBaseContext: handoff.firstBaseContext } : {}),
      ballContext: handoff.ballContext,
      physicalIdentity: handoff.physicalTruth?.identity || "",
      ...(handoff.receiverSourcePin ? { receiverSourcePin: handoff.receiverSourcePin } : {}),
      runnerRealization: handoff.runnerRealization,
      forceState: handoff.forceState,
      timingWindows: handoff.timingWindows,
      presentationText
    },
    legalRoutes: legalChoices,
    recommendation: {
      direction: match.coachTacticalDirection ? JSON.parse(JSON.stringify(match.coachTacticalDirection)) : null,
      presentation: match.coachInstruction || ""
    },
    previousSituationSummary: match.lastClosedSituationSummary || null
  });
  situation = MatchSituationLifecycle.admitSituation(situation, {
    supported: true,
    playerOwnsDecision: classification?.eventClassification === "playerMeaningfulDecision",
    reason: classification?.eventClassification === "playerMeaningfulDecision"
      ? "groundBallMultipleMeaningfulRoutes" : "groundBallAutomaticResolution"
  });
  if (situation.admission.admittedToPlayer) situation = MatchSituationLifecycle.presentSituation(situation);
  match.activeSituation = situation;
  return situation;
}

function resolveHighSchoolDefensivePlay(match, decision, randomSource = Math.random) {
  const pending = match?.activeSituation;
  if ((match?.groundBallInPlayState?.runnerThrowTiming || match?.groundBallInPlayState?.shortstopExecution) && pending?.lifecycleState === "resolved" && pending.resolution?.executionEvidence) {
    validateHighSchoolDecisionThrowState(match);
    const selected = pending.legalRoutes.find(route => route.matchDecision === decision || route.routeId === decision);
    if (!selected || (selected.routeId || selected.matchDecision) !== pending.decision?.selectedRoute) throw new Error("Stale defensive decision after execution");
    return pending.resolution.executionEvidence;
  }
  if (match?.positionDecisionFamily === "infield" && match.defensiveSituation?.familyId === "infield") {
    if (match.defensiveSituation.groundBallDefensiveContext?.supported) {
      assertHighSchoolGroundParticipant(match);
    }
    return infieldDecisionFamily.resolve(match.defensiveSituation, decision, match, randomSource);
  }
  if (match?.position === "捕手") return resolveHighSchoolCatcherDecision(match, decision, randomSource);
  return resolveLegacyHighSchoolDefensivePlay(match, decision, randomSource);
}

function recordGroundBallSituationResolution(match, resolution) {
  if (!match || !resolution || typeof MatchSituationLifecycle === "undefined") return null;
  let situation = MatchSituationLifecycle.normalizeSituation(match.activeSituation);
  if (!situation || situation.type !== MatchSituationLifecycle.TYPES.groundBallDefensiveDecision
    || situation.lifecycleState !== "executing") return situation;
  validateHighSchoolDecisionThrowState(match);
  const handoff = match.groundBallInPlayState;
  if (handoff?.firstBaseExecution && Object.entries(handoff.firstBaseExecution.resolution)
    .some(([key, value]) => JSON.stringify(resolution[key]) !== JSON.stringify(value))) throw new Error("Stale first-base settlement execution facts");
  if (handoff?.thirdBaseExecution && Object.entries(handoff.thirdBaseExecution.resolution)
    .some(([key, value]) => JSON.stringify(resolution[key]) !== JSON.stringify(value))) throw new Error("Stale 3B settlement execution facts");
  if (handoff?.shortstopExecution && Object.entries(handoff.shortstopExecution.resolution)
    .some(([key, value]) => JSON.stringify(resolution[key]) !== JSON.stringify(value))) throw new Error("Stale SS settlement execution facts");
  if (handoff?.supported && !handoff.settlementApplied && !handoff.secureResolution
    && handoff.defensiveAccess?.reachResolution && resolution.playerLeg?.control
    && typeof DefensiveReachSecureFoundation !== "undefined") {
    assertHighSchoolDetailedResponsibility(match, handoff.physicalTruth, "2B", "player");
    const securedHandoff = BattedBallGroundDefense.normalizeHandoff({ ...handoff,
      secureResolution: DefensiveReachSecureFoundation.projectGroundControl(handoff.defensiveAccess.reachResolution, resolution.playerLeg.control, resolution.controlEvidence) });
    const decisionThrowState = projectHighSchoolControlledDecisionThrow(match, resolution, securedHandoff);
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...securedHandoff, ...(decisionThrowState ? { decisionThrowState } : {}) });
    if (decisionThrowState && typeof DefensiveRunnerThrowSettlementFoundation !== "undefined") {
      const route = decisionThrowState.activeSelection?.route || decisionThrowState.selection?.route;
      const receiverFact = route?.routeId === "initiate463" ? resolution.teammateLeg?.shortstopReceive
        : route?.routeId === "preventRunHome" && !resolution.reassessed ? resolution.teammateLeg?.catcherReceive : resolution.teammateLeg?.receiver;
      const runnerThrowTiming = DefensiveRunnerThrowSettlementFoundation.projectExistingTiming({ stage: decisionThrowState,
        runnerState: handoff.runnerPhysicalStates?.find(r => r.runnerId === route?.targetRunnerId),
        windowState: resolution.firstLegTimingWindow?.state || "expired", receiverFact: receiverFact || "unavailable",
        tagFact: resolution.homeTagLeg?.arrivalComparison || null });
      match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...match.groundBallInPlayState, runnerThrowTiming });
    }
  }
  if (resolution.reassessment) {
    const remaining = (resolution.reassessment.availableRouteIds || []).map(routeId => ({ routeId }));
    situation = MatchSituationLifecycle.beginReassessment(situation, {
      trigger: resolution.reassessment.reason,
      updatedPhysicalState: {
        firstLegState: resolution.firstLegState || null,
        continuationState: resolution.continuationState || null,
        forceState: resolution.reassessment.forceState || null
      },
      remainingLegalRoutes: remaining,
      requiresDecision: false,
      firstLegApplied: resolution.firstLegState?.status === "completed"
    });
  }
  situation = MatchSituationLifecycle.resolveSituation(situation, {
    physicalOutcomeRef: `${situation.situationId}|physical-resolution`,
    outsDelta: resolution.outsCreated,
    runsDelta: resolution.runsAllowed,
    runnerActorOutcomes: resolution.runnerChanges,
    executionEvidence: match.groundBallInPlayState?.runnerThrowTiming || match.groundBallInPlayState?.shortstopExecution ? resolution : null,
    reason: resolution.reassessment ? "postExecutionReassessmentComplete" : "groundBallExecutionComplete"
  });
  match.activeSituation = situation;
  return situation;
}

function applyInfieldResolutionToHighSchoolMatch(match, decision, resolution) {
  const situation = match.defensiveSituation;
  const groundBallContext = situation?.groundBallDefensiveContext;
  if (resolution.runnerSettlementIdentity && match.lastDefensiveResolution?.runnerSettlementIdentity === resolution.runnerSettlementIdentity) return match.completedMoments.at(-1) || null;
  if (resolution.runnerSettlementIdentity && resolution.runnerSettlementIdentity !== situation?.runnerSettlementIdentity) throw new Error("Stale infield play identity");
  if (groundBallContext && match.groundBallInPlayState?.settlementApplied) return match.completedMoments.at(-1) || null;
  validateHighSchoolDecisionThrowState(match);
  beginGroundBallSituationDecision(match, decision);
  recordGroundBallSituationResolution(match, resolution);
  validateHighSchoolStoredDefensiveResolution(match, resolution);
  const situationBefore = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
  const presentation = infieldDecisionFamily.present(situation, resolution, decision);
  const explanation = resolution.defensiveOutcomeExplanation || createDefensiveOutcomeExplanation(situation, getInfieldDecisionChoice(situation, match, decision), resolution);
  const thirdOutResolution = finalizeHighSchoolDefensiveThirdOut(match, situationBefore, resolution);
  const runnerChanges = normalizeHighSchoolTerminalRunnerChanges(resolution, thirdOutResolution);
  if (match.groundBallInPlayState?.runnerThrowTiming && typeof DefensiveRunnerThrowSettlementFoundation !== "undefined") {
    const handoff = match.groundBallInPlayState;
    const settlement = DefensiveRunnerThrowSettlementFoundation.projectExistingSettlement({ timing: handoff.runnerThrowTiming,
      stage: handoff.decisionThrowState, before: situationBefore, resolution, thirdOut: thirdOutResolution });
    const applied = applyHighSchoolDefensiveSettlementFacts(match, settlement, "infield-decision-family");
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({ ...handoff, playSettlement: applied });
  } else {
    const settlement = DefensiveRunnerThrowSettlementFoundation.projectInfieldSettlement({
      identity: situation.runnerSettlementIdentity, before: situationBefore, resolution, thirdOut: thirdOutResolution });
    applyHighSchoolDefensiveSettlementFacts(match, settlement, "infield-decision-family");
  }
  resolution = projectHighSchoolInfieldScoredResolution(match, situation, resolution);
  if (resolution.error) match.playerContribution.errors += 1;
  match.playerContribution.outsCreated += resolution.outsCreated;
  syncHighSchoolMatchPlayerRunnerLocation(match);
  const situationAfter = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
  const consequence = resolution.route === "doublePlay" && resolution.outsCreated === 1
    ? `${resolution.causeExplanation} 合理的雙殺判斷只完成一半。` : resolution.causeExplanation;
  const provisionalResolution = {
    ...resolution,
    runnerChanges,
    runnersAfter: thirdOutResolution.basesAfter,
    scoringRunnerIds: thirdOutResolution.legalScoringRunnerIds,
    runsAllowed: thirdOutResolution.legalScoringRunnerIds.length,
    thirdOutResolution
  };
  // Player error attribution stays separate from the team's official PA result.
  const thirdBaseTeamError = resolution.scorerFacts ? resolution.scorerFacts.batterReachedOnError
    : (resolution.thirdBaseEvidence || resolution.firstBaseEvidence) && resolution.actionFacts.actions
      .some(action => action.errorCharged === true && action.status === "failed");
  const groundBallPhysicalOutcome = groundBallContext && typeof BattedBallGroundDefense !== "undefined"
    ? BattedBallGroundDefense.settleGroundBallPhysicalOutcome(groundBallContext, provisionalResolution) : null;
  const paCompatibilityResult = groundBallPhysicalOutcome && typeof BattedBallGroundDefense !== "undefined"
    ? BattedBallOutcomeMapping.resolveOfficialBallInPlayOutcome({
      physicalTruth: groundBallContext.physicalTruth,
      defenseOutcome: { ...BattedBallGroundDefense.derivePACompatibilityResult(groundBallPhysicalOutcome), settled: true }
    }) : null;
  const batterResult = resolution.batterScoring?.classification === "fieldersChoice" ? "out"
    : (resolution.scorerFacts ? thirdBaseTeamError : resolution.error || thirdBaseTeamError) ? "error"
    : paCompatibilityResult?.result || (resolution.outsCreated > 0 ? "out" : "single");
  const appliedResolution = {
    ...provisionalResolution,
    groundBallPhysicalOutcome,
    paCompatibilityResult,
    ...getHighSchoolInfieldFinalFacts(match, situation, resolution)
  };
  const paEvent = recordHighSchoolMeaningfulPlateAppearance(match, situation.batterId, batterResult, situationBefore, situationAfter, thirdOutResolution.legalScoringRunnerIds.length, appliedResolution);
  if (paCompatibilityResult) Object.assign(paEvent, { physicalOutcomeFlow: "physicalTruthToOfficialOutcome", officialBallInPlayOutcome: JSON.parse(JSON.stringify(paCompatibilityResult)) });
  getHighSchoolMatchPerformanceEvidence(match, "player").defensiveInvolvements += 1;
  recordHighSchoolYearOneMoment(match, decision, resolution.tier, explanation?.outcome || presentation.outcome, consequence, situationAfter, {
    runnerChanges,
    scoringRunnerIds: thirdOutResolution.legalScoringRunnerIds,
    thirdOutResolution,
    resultCode: resolution.resultCode,
    error: resolution.error,
    defensiveFacts: getHighSchoolInfieldFinalFacts(match, situation, resolution)
  });
  match.lastDefensiveResolution = JSON.parse(JSON.stringify(appliedResolution));
  if (match.buntBallInPlayState && situation.buntDefensiveContext) {
    match.buntBallInPlayState = Object.freeze({
      ...JSON.parse(JSON.stringify(match.buntBallInPlayState)),
      firstLegState: resolution.firstLegState ? JSON.parse(JSON.stringify(resolution.firstLegState)) : { status: "notSelected", targetBase: "" },
      continuationState: resolution.continuationState ? JSON.parse(JSON.stringify(resolution.continuationState)) : { status: "notApplicable", window: "", targetBase: "" }
    });
  }
  if (groundBallPhysicalOutcome && groundBallContext) {
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({
      ...JSON.parse(JSON.stringify(match.groundBallInPlayState || groundBallContext)),
      firstLegState: JSON.parse(JSON.stringify(groundBallPhysicalOutcome.firstLegState)),
      continuationState: JSON.parse(JSON.stringify(groundBallPhysicalOutcome.continuationState)),
      chosenRoute: resolution.initialRoute || resolution.routeId || decision || "",
      finalRoute: resolution.activeRoute || resolution.routeId || resolution.route || "",
      physicalOutcome: JSON.parse(JSON.stringify(groundBallPhysicalOutcome)),
      paCompatibilityResult: JSON.parse(JSON.stringify(paCompatibilityResult)),
      settlementApplied: true
    });
    if (match.ordinaryDefensivePlateAppearanceState && typeof OffensivePlateApproach !== "undefined") {
      match.ordinaryDefensivePlateAppearanceState = OffensivePlateApproach.markResultApplied({ ...match.ordinaryDefensivePlateAppearanceState, result: batterResult, completed: true, officialBallInPlayOutcome: paCompatibilityResult });
    }
  }
  const densityState = ensureHighSchoolMatchDecisionDensityState(match);
  densityState.lastSelectedRoute = resolution.initialRoute || resolution.routeId || decision || "";
  densityState.lastFinalRoute = resolution.activeRoute || resolution.routeId || resolution.route || "";
  Object.assign(match.completedMoments.at(-1), {
    ...getHighSchoolInfieldFinalFacts(match, situation, resolution),
    positionDecisionFamily: "infield",
    playerPosition: situation.playerPosition,
    route: resolution.route,
    resultCode: resolution.resultCode,
    detailedResult: resolution.detailedResult,
    decisionQuality: resolution.decisionQuality,
    executionQuality: resolution.executionQuality,
    outsCreated: resolution.outsCreated,
    runnerChanges: runnerChanges.map(change => ({ ...change })),
    scoringRunnerIds: thirdOutResolution.legalScoringRunnerIds.slice(),
    runsAllowed: thirdOutResolution.legalScoringRunnerIds.length,
    thirdOutResolution: JSON.parse(JSON.stringify(thirdOutResolution)),
    error: resolution.error,
    primaryCause: resolution.primaryCause,
    secondaryCause: resolution.secondaryCause,
    responsibleActor: resolution.responsibleActor || "",
    playerRole: resolution.playerRole || situation.responsibility?.playerRole || "",
    initialRoute: resolution.initialRoute || resolution.routeId || "",
    activeRoute: resolution.activeRoute || resolution.routeId || "",
    fallbackRoute: resolution.fallbackRoute || "",
    executionStage: resolution.executionStage || "",
    playerResponsibility: resolution.playerResponsibility,
    teammateResponsibility: resolution.teammateResponsibility,
    playerLeg: resolution.playerLeg ? JSON.parse(JSON.stringify(resolution.playerLeg)) : {},
    teammateLeg: resolution.teammateLeg ? JSON.parse(JSON.stringify(resolution.teammateLeg)) : {},
    timingResolution: resolution.timingResolution ? JSON.parse(JSON.stringify(resolution.timingResolution)) : {},
    defensiveOutcomeExplanation: explanation ? JSON.parse(JSON.stringify(explanation)) : null,
    executionText: explanation?.executionSummary || presentation.execution,
    causeExplanation: explanation?.causeText || resolution.causeExplanation,
    coachFeedback: explanation?.coachFeedback || "",
    ballContext: resolution.ballContext,
    ballDirection: resolution.ballDirection,
    ballDepth: resolution.ballDepth,
    groundBallPhysicalOutcome: groundBallPhysicalOutcome ? JSON.parse(JSON.stringify(groundBallPhysicalOutcome)) : null,
    paCompatibilityResult: paCompatibilityResult ? JSON.parse(JSON.stringify(paCompatibilityResult)) : null
  });
  recordHighSchoolMatchSimulationEvent(match, {
    type: "defensiveResolution", presentationImportance: "hidden", inning: match.inning, half: match.half,
    ...getHighSchoolInfieldFinalFacts(match, situation, resolution),
    ...(match.groundBallInPlayState?.shortstopExecution ? { playerPosition: situation.playerPosition,
      situationId: match.activeSituation?.situationId, decisionIdentity: match.groundBallInPlayState.decisionThrowState.selection?.identity
        || `${match.activeSituation?.situationId}|decision|${resolution.initialRoute}`,
      decisionProvenance: match.activeSituation?.decision || null, contextSnapshot: match.activeSituation?.contextSnapshot,
      availableOptions: match.activeSituation?.legalRoutes, physicalIdentity: match.groundBallInPlayState.physicalTruth.identity } : {}),
    familyId: "infield", route: resolution.route, routeId: resolution.routeId || "", initialRoute: resolution.initialRoute || "", activeRoute: resolution.activeRoute || "", fallbackRoute: resolution.fallbackRoute || "", resultCode: resolution.resultCode,
    playerRole: resolution.playerRole || situation.responsibility?.playerRole || "", primaryCause: resolution.primaryCause, responsibleActor: resolution.responsibleActor || "",
    decisionQuality: resolution.decisionQuality, executionQuality: resolution.executionQuality,
    secondaryCause: resolution.secondaryCause || "", playerResponsibility: resolution.playerResponsibility || "", teammateResponsibility: resolution.teammateResponsibility || "",
    playerLeg: resolution.playerLeg || {}, teammateLeg: resolution.teammateLeg || {}, timingResolution: resolution.timingResolution || {},
    outsCreated: resolution.outsCreated, runsAllowed: appliedResolution.runsAllowed,
    runnerChanges, scoringRunnerIds: thirdOutResolution.legalScoringRunnerIds, thirdOutResolution,
    groundBallPhysicalOutcome, paCompatibilityResult,
    outs: match.outs, scores: match.scores, runners: match.runners
  });
  advanceHighSchoolMatchBattingOrder(match, getHighSchoolOpponentTeamSide(match));
  assertHighSchoolMatchStateIntegrity(match, "player-defense-decision");
  settleAndCloseGroundBallSituation(match);
  restoreHighSchoolMatchAfterDefensiveDecision(match);
  match.currentAssignment = "等待球隊完成這個守備半局。";
  match.coachReaction = explanation?.coachFeedback || "現任教練提醒你先確認跑者，再決定最短的出局路線。";
  match.teamReaction = resolution.teammateResponsibility === "major"
    ? formatHighSchoolMatchWorldState(match, "接球隊友舉手示意這一球由他負責。")
    : formatHighSchoolMatchWorldState(match);
  return match.completedMoments.at(-1);
}

function prepareCurrentHighSchoolYearOneMatch() {
  if (getCurrentEventId() === "critical_tournament" && isCanonicalHighSchoolYearThreeRoute()) return prepareHighSchoolYearThreeMatch();
  if (getCurrentEventId() === "high_school_year_two_autumn_stage" && isHighSchoolYearOneMatchEventId("high_school_year_two_autumn_stage")) {
    return prepareHighSchoolYearTwoAutumnMatch();
  }
  if (getCurrentEventId() === "high_school_year_two_spring_game" && isHighSchoolYearOneMatchEventId("high_school_year_two_spring_game")) {
    return prepareHighSchoolYearTwoEvaluationMatch();
  }
  return getCurrentEventId() === "high_school_followup_evaluation"
    ? prepareHighSchoolFollowupEvaluationMatch()
    : prepareHighSchoolYearOneMatch();
}

function resolveHighSchoolYearOneMatch(decision, expectedMomentId = "", randomSource = Math.random) {
  const match = prepareCurrentHighSchoolYearOneMatch();
  if (match.simulationPhase === "offensive_agency_ready") {
    const agencySelection = decision === "agencyManual" ? "manual" : decision === "agencySimulate" ? "simulate" : "";
    return agencySelection ? chooseHighSchoolOffensiveAgency(agencySelection, expectedMomentId || match.offensivePlayerAgencyState?.momentId) : false;
  }
  const activeSituation = typeof MatchSituationLifecycle !== "undefined"
    ? MatchSituationLifecycle.normalizeSituation(match.activeSituation) : null;
  if (activeSituation?.type === "plateDecision") {
    if (expectedMomentId && expectedMomentId !== getHighSchoolYearOneMomentId(match)) return false;
    const legalRoute = activeSituation.legalRoutes.find(route => route.routeId === decision || route.matchDecision === decision);
    if (!legalRoute) return false;
    const resolvedPitch = resolveHighSchoolPlateDecisionPitch(match, legalRoute.routeId);
    if (!resolvedPitch) return false;
    const pitchText = formatHighSchoolPlateDecisionPitchResult(resolvedPitch.event);
    if (!resolvedPitch.plateAppearanceCompleted) return pitchText;
    const selectedChoice = resolvedPitch.selectedOffensiveChoice || match.plateDecisionState?.selectedOffensiveChoice;
    const completed = match.momentIndex === 0
      ? advanceHighSchoolYearOneAfterMomentOne(match, selectedChoice, null)
      : resolveHighSchoolYearOneFinalMoment(match, selectedChoice, null);
    return completed ? `${pitchText} ${match.completedMoments.at(-1).outcome}。${match.completedMoments.at(-1).consequence}` : false;
  }
  if (activeSituation?.type === "runnerTagUpDecision") {
    if (expectedMomentId && expectedMomentId !== match.currentMomentId) return false;
    const legalRoute = activeSituation.legalRoutes.find(route => route.routeId === decision || route.matchDecision === decision);
    if (!legalRoute) return false;
    const closed = resolveHighSchoolRunnerTagUpDecision(match, legalRoute.routeId, { randomSource });
    const outcome = match.lastClosedSituationSummary?.outcome || closed?.resolution?.reason || "";
    return outcome === "safeHome" ? "你衝回本壘得分。" : outcome === "taggedOutAtHome" ? "你在本壘前被觸殺出局。" : "你留在三壘。";
  }
  const currentMomentId = getHighSchoolYearOneMomentId(match);
  const legalChoices = getHighSchoolYearOneMatchMomentChoices(match);
  const legalChoice = legalChoices.find(choice => choice.matchDecision === decision);
  const expectedPhase = `moment_${match.momentIndex + 1}_ready`;
  if (match.completed || match.simulationPhase !== expectedPhase || !currentMomentId || (expectedMomentId && expectedMomentId !== currentMomentId) || !legalChoice) return false;
  if (match.completedMoments.some(moment => moment.id === currentMomentId)) return false;
  if (match.momentIndex === 0) {
    if (!advanceHighSchoolYearOneAfterMomentOne(match, legalChoice, null)) return false;
    return `${match.completedMoments.at(-1).outcome}。${match.completedMoments.at(-1).consequence}`;
  }
  if (match.momentIndex === 1) {
    beginGroundBallSituationDecision(match, decision);
    const defensiveResolution = resolveHighSchoolDefensivePlay(match, decision, randomSource);
    recordGroundBallSituationResolution(match, defensiveResolution);
    const tier = defensiveResolution?.tier || "failure";
    advanceHighSchoolYearOneAfterMomentTwo(match, decision, tier, defensiveResolution);
    return `${match.completedMoments.at(-1).outcome}。${match.completedMoments.at(-1).consequence}`;
  }
  return resolveHighSchoolYearOneFinalMoment(match, legalChoice, null);
}

function resolveStartingOpportunity(input = {}) {
  const readiness = input.readinessSnapshot;
  if (!readiness || readiness.version !== READINESS_VERSION) {
    throw new Error("Playing-Time Opportunity requires a valid Opportunity Readiness Snapshot.");
  }
  const matchId = String(input.matchId || "match");
  const playerId = String(readiness.playerId || "player");
  const actualRole = normalizeActualRole(input.actualRole);
  const coachUsageStyle = normalizeCoachUsageStyle(input.coachUsageStyle || input.coachStyle);
  const positionCapability = clamp(readiness.positionReadiness, 0, 10, 5);
  const positionFit = clamp(readiness.positionFit, 0, 10, 5);
  const positionExperience = clamp(readiness.experienceReadiness, 0, 10, 5);
  const position = {
    requested: normalizePosition(readiness.requestedPosition),
    assigned: normalizePosition(readiness.position),
    legal: readiness.positionLegal === true,
    pitcherExposureDeferred: readiness.pitcherExposureDeferred === true,
    fallbackApplied: readiness.positionFallbackApplied === true
  };
  const directStartForced = input.directStartForced === true;
  const gameContext = input.gameContext || {};
  const previousActualExposure = input.previousActualExposure ? {
    appearanceType: input.previousActualExposure.appearanceType || "noAppearance",
    plateAppearances: Math.max(0, Number(input.previousActualExposure.plateAppearances) || 0),
    defensiveInnings: Math.max(0, Number(input.previousActualExposure.defensiveInnings) || 0)
  } : null;
  const evaluationTrend = clamp(input.evaluationTrend, -4, 4, 0);
  const coachTrust = input.coachTrust === undefined ? null : clamp(input.coachTrust, 0, 10, 5);
  const health = input.health && typeof input.health === "object" ? input.health : null;
  const healthReadiness = health
    ? -Math.round(clamp(health.fatigue, 0, 20, 0) * 0.45 + clamp(health.pain, 0, 20, 0) * 0.8 + clamp(health.injuryRisk, 0, 20, 0) * 0.35)
    : null;
  const decisionIdentityParts = [OPPORTUNITY_VERSION, matchId, playerId, input.opportunitySeed || "", actualRole,
    input.projectedRole || "", input.playingTimeEnvironment || "medium", input.competitionDepth || "medium",
    input.positionNeed || "medium", coachUsageStyle, position.assigned, positionCapability, positionFit, positionExperience,
    gameContext.gameType || "game", gameContext.inning || 0, gameContext.scoreMargin || 0,
    gameContext.expectedGameImportance || gameContext.importance || "regular", gameContext.leverage || "normal"];
  if (input.evaluationTrend !== undefined) decisionIdentityParts.push(evaluationTrend);
  if (coachTrust !== null) decisionIdentityParts.push(coachTrust);
  if (healthReadiness !== null) decisionIdentityParts.push(healthReadiness);
  if (previousActualExposure) decisionIdentityParts.push([previousActualExposure.appearanceType, previousActualExposure.plateAppearances, previousActualExposure.defensiveInnings].join(":"));
  const decisionIdentity = decisionIdentityParts.join("|");
  const opportunityHash = stableHash(input.stableVariationSeed || decisionIdentity);
  const hashVariation = (opportunityHash % 31) - 15;
  const scoreBreakdown = {
    actualRole: ROLE_BASE[actualRole],
    positionCapability: Math.round((positionCapability - 5) * 4),
    positionFit: Math.round((positionFit - 5) * 2),
    positionExperience: Math.round((positionExperience - 5) * 1.5),
    schoolEnvironment: ENVIRONMENT_MODIFIER[input.playingTimeEnvironment] ?? ENVIRONMENT_MODIFIER.medium,
    competitionDepth: COMPETITION_MODIFIER[input.competitionDepth] ?? COMPETITION_MODIFIER.medium,
    positionNeed: POSITION_NEED_MODIFIER[input.positionNeed] ?? POSITION_NEED_MODIFIER.medium,
    projectedRolePrior: PROJECTED_ROLE_PRIOR[input.projectedRole] ?? 0,
    coachUsage: deriveCoachModifier(coachUsageStyle, actualRole, positionCapability),
    gameContext: deriveGameContextModifier(gameContext),
    deterministicVariation: hashVariation
  };
  if (input.evaluationTrend !== undefined) scoreBreakdown.evaluationTrend = Math.round(evaluationTrend);
  if (coachTrust !== null) scoreBreakdown.coachTrust = Math.round((coachTrust - 5) * 1.5);
  if (healthReadiness !== null) scoreBreakdown.healthReadiness = healthReadiness;
  const opportunityScore = Object.values(scoreBreakdown).reduce((sum, value) => sum + Number(value || 0), 0);
  let plannedUsage = resolvePlannedAppearance(opportunityScore, actualRole, coachUsageStyle, opportunityHash);
  let exposureSource = "opportunity-resolver";
  if (directStartForced && !position.pitcherExposureDeferred) {
    plannedUsage = { appearanceType: "start", entryInning: 1, entryHalf: "上" };
    exposureSource = "direct-start-forced";
  }
  if (position.pitcherExposureDeferred || !position.legal) plannedUsage = { appearanceType: "noAppearance", entryInning: null, entryHalf: "" };
  const reasons = [
    `actual-role:${actualRole}`,
    `school-environment:${input.playingTimeEnvironment || "medium"}`,
    `competition-depth:${input.competitionDepth || "medium"}`,
    `position-need:${input.positionNeed || "medium"}`,
    `coach-usage:${coachUsageStyle}`,
    position.fallbackApplied ? `legal-position-fallback:${position.assigned}` : "position-legal"
  ];
  if (position.pitcherExposureDeferred) reasons.push("pitcher-exposure-deferred");
  if (!position.legal) reasons.push("position-illegal");
  const startingOpportunity = plannedUsage.appearanceType === "start" ? "start" : actualRole === "rotation" ? "rotationCandidate" : "bench";
  return deepFreeze({
    version: OPPORTUNITY_VERSION,
    sourceVersion: OPPORTUNITY_VERSION,
    decisionId: `${matchId}|${playerId}|${opportunityHash.toString(16).padStart(8, "0")}`,
    matchId,
    playerId,
    exposureSource,
    actualRole,
    actualRoleAtDecision: actualRole,
    projectedRolePrior: input.projectedRole || "",
    playingTimeEnvironment: input.playingTimeEnvironment || "medium",
    schoolPlayingTimeEnvironment: input.playingTimeEnvironment || "medium",
    competitionDepth: input.competitionDepth || "medium",
    positionCompetition: input.competitionDepth || "medium",
    positionNeed: input.positionNeed || "medium",
    evaluationTrend,
    previousActualExposure,
    coachUsageStyle,
    positionCapability,
    positionFit,
    positionExperience,
    assignedPosition: position.assigned,
    requestedPosition: position.requested,
    positionFallbackApplied: position.fallbackApplied,
    assignmentSource: readiness.assignmentSource || (position.fallbackApplied ? "position-fallback" : "requested-position"),
    assignmentReason: readiness.assignmentReason || (position.fallbackApplied ? `legal-position-fallback:${position.assigned}` : "specific-position-request"),
    pitcherExposureDeferred: position.pitcherExposureDeferred,
    startingOpportunity,
    startingDecision: startingOpportunity,
    appearancePlan: plannedUsage,
    substitutionOpportunity: plannedUsage.appearanceType === "start" ? "none" : plannedUsage.appearanceType,
    opportunityReasons: reasons,
    opportunitySeed: decisionIdentity,
    gameContext: clone(gameContext),
    readinessSnapshot: clone(readiness),
    plannedUsage,
    debug: { opportunityHash, opportunityScore, scoreBreakdown, reasons }
  });
}

function resolveDefensiveOpportunity({ physicalTruth, activeRoster, topologyVersion = TOPOLOGY_VERSION } = {}) {
  const opportunity = deriveDefensiveOpportunity(physicalTruth, topologyVersion);
  if (!opportunity.supported) return opportunity;
  const assignment = Roster.validateActiveDefense(activeRoster);
  if (!assignment.ok) return freeze({ ...opportunity, supported: false, bindingStatus: "invalid",
    fallbackReason: "invalidActiveAssignment", assignmentIssues: assignment.issues.slice() });
  const primary = Roster.getCurrentDefender(activeRoster, opportunity.primaryPosition);
  const secondaryDefenders = opportunity.secondaryPositions.map(position => ({
    position, defenderId: Roster.getCurrentDefender(activeRoster, position)?.id || ""
  }));
  if (!primary || secondaryDefenders.some(actor => !actor.defenderId)) {
    return freeze({ ...opportunity, supported: false, bindingStatus: "invalid", fallbackReason: "activeDefenderUnavailable" });
  }
  return freeze({ ...opportunity, primaryDefenderId: primary.id, secondaryDefenders, bindingStatus: "bound" });
}

function resolveBattedBallPhysicalTruth(input = {}) {
  const identity = String(input.identity || "ordinary-contact");
  const quality = resolveContactQuality({ ...input, identity });
  const ballType = resolveBattedBallType({ ...input, identity, contactQuality: quality.contactQuality });
  const pace = resolveBattedBallPace({ ...input, identity, contactQuality: quality.contactQuality, ballType });
  const direction = resolveBattedBallDirection({ ...input, identity });
  const depth = resolveBattedBallDepth({ ...input, identity, contactQuality: quality.contactQuality, ballType });
  return deepFreeze({
    version: VERSION,
    identity,
    contactQuality: quality.contactQuality,
    ballType,
    pace: pace.pace,
    direction: direction.direction,
    depth: depth.depth,
    executionEvidence: {
      actualPitch: clone(input.actualPitch || {}),
      recognition: clone(input.recognition || {}),
      swing: { action: input.action || "swing", contact: input.contact === true, swingIntent: input.swingIntent || "normal" },
      continuousContactScore: quality.score,
      paceScore: pace.score,
      depthScore: depth.score,
      rolls: { contactQuality: quality.roll, ballType: resolveRoll(input, "ballType", RNG_NAMESPACES.ballType, identity), pace: pace.roll, direction: direction.roll, depth: depth.roll },
      depthRollConsumed: depth.consumed
    }
  });
}

function resolveReach(input = {}) {
  const op = binding(input);
  const identity = `${op.identity}|${op.primaryDefenderId}|reach-v1`;
  const ballDemand = demand(op);
  const caps = input.capabilities;
  const inputs = { reaction: ability(caps.reaction), range: ability(caps.range), mobility: ability(caps.mobility ?? caps.range) };
  const movement = inputs.range * 0.75 + inputs.mobility * 0.25;
  const variationIdentity = `${op.executionIdentity || op.identity}|${op.primaryDefenderId}|reach-v1`;
  const evidence = variation("reach", variationIdentity, input.roll);
  const margin = round(inputs.reaction * ballDemand.reactionWeight + movement * (1 - ballDemand.reactionWeight)
    - ballDemand.reachDemand + evidence.adjustment);
  return freeze({ version: VERSION, identity, opportunityIdentity: op.identity, physicalIdentity: op.physicalIdentity,
    defenderId: op.primaryDefenderId, position: op.primaryPosition, supported: true,
    authority: "physicalOpportunity+activeDefender+reachCapabilities",
    reachDemand: ballDemand.reachDemand, reactionDemand: ballDemand.reactionDemand, movementDemand: ballDemand.movementDemand,
    responsibilityClassification: op.responsibilityClassification, ballDemand, inputs, margin,
    reached: margin >= 0, reachQuality: margin >= 1.25 ? "cleanArrival" : margin >= 0 ? "stretchedArrival" : "notReached",
    variationEvidence: evidence });
}

function resolveSecure(input = {}) {
  const reach = validateReach(input);
  const base = secureBase(reach);
  if (!reach.reached) return freeze({ ...base, secureDemand: null, secureQuality: "notAttempted", secured: false,
    ballState: "notReached", variationEvidence: { namespace: RNG_NAMESPACES.secure, consumed: false, roll: null } });
  const ball = input.opportunity.ballContext;
  const fielding = ability(input.capabilities.fielding ?? input.capabilities.catching);
  const catching = ability(input.capabilities.catching ?? input.capabilities.fielding);
  const ground = ball.ballType === "groundBall";
  const pressure = { weak: 2.5, moderate: 3.5, firm: 4.5, hard: 6 }[ball.pace]
    + (ball.ballType === "lineDrive" ? 1 : ball.ballType === "flyBall" ? -1 : 0);
  const arrivalPenalty = reach.reachQuality === "stretchedArrival" ? 2 : 0;
  const secureDemand = pressure + arrivalPenalty;
  const variationIdentity = `${reach.variationEvidence?.identity || reach.identity}|secure-v1`;
  const evidence = variation("secure", variationIdentity, input.roll);
  const margin = round((ground ? fielding * 0.75 + catching * 0.25 : catching * 0.8 + fielding * 0.2)
    - secureDemand + evidence.adjustment);
  const secured = margin >= 0;
  return freeze({ ...base, secureDemand, margin, secured,
    secureQuality: ground ? (margin >= 1.5 ? "cleanControl" : secured ? "bobbleButControlled" : "notControlled")
      : secured ? "caughtBeforeGround" : "notCaught",
    ballState: secured ? "secured" : ground ? "looseLiveBall" : "groundContactLive",
    inputs: { ...base.inputs, fielding, catching, ballType: ball.ballType, pace: ball.pace, pressure, arrivalPenalty },
    variationEvidence: evidence });
}
// Existing 2B control remains the sole control authority for that validated vertical.
// This adapter records its physical fact; it never rolls or interprets outs/throws.

function resolveThrow({ input, opportunity, selection, capabilities, rolls, transferState } = {}) {
  validateSelection(selection, opportunity, input);
  const base = throwBase(selection);
  if (selection.route.action === "baseTouch") fail("base touch cannot resolve a throw");
  if (selection.route.action === "holdBall") return freeze({ ...base, throwAttempted: false, throwQuality: "notAttempted",
    releaseQuality: "held", ballArrivalState: "controlledByThrower", variationEvidence: { consumed: false }, authority: "deliberateHold" });
  if (!["ready", "completed", "delayed", "failed"].includes(transferState)) fail("unknown transfer readiness");
  if (transferState === "failed") return freeze({ ...base, throwAttempted: false, throwQuality: "notAttempted",
    releaseQuality: "transferUnavailable", ballArrivalState: "releaseUnavailable", variationEvidence: { consumed: false }, authority: "upstreamTransfer" });
  if (capabilities?.defenderId !== selection.defenderId || !Number.isFinite(capabilities.arm) || !Number.isFinite(capabilities.throwing)) fail("throw capability adapter mismatch");
  const demand = throwDemand(selection, input.secureResult);
  const sample = stage => { const explicit = rolls?.[stage]; const namespace = RNG_NAMESPACES[stage];
    const roll = Number.isFinite(explicit) ? Math.max(0, Math.min(1, explicit)) : Physical.deterministicUnit(namespace, base.identity, stage);
    return { namespace, roll, adjustment: (0.5 - roll) * 2 }; };
  const strengthVariation = sample("strength"), accuracyVariation = sample("accuracy");
  const arm = Math.max(0, Math.min(20, capabilities.arm)), throwing = Math.max(0, Math.min(20, capabilities.throwing));
  const strengthMargin = arm - demand.strength + strengthVariation.adjustment;
  const accuracyMargin = throwing - demand.accuracy + accuracyVariation.adjustment;
  const quality = accuracyMargin < -1 ? "offline" : strengthMargin < 0 ? "lateWeakThrow" : accuracyMargin < 1 ? "challengingReceive" : "onTarget";
  return freeze({ ...base, throwAttempted: true, throwDemand: demand, strengthMargin, accuracyMargin,
    throwQuality: quality, releaseQuality: transferState === "delayed" ? "delayedRelease" : "readyRelease",
    ballArrivalState: { offline: "outsideReceiverReach", lateWeakThrow: "insufficientDelivery", challengingReceive: "receiverChallenged", onTarget: "atReceiverTarget" }[quality],
    inputs: { arm, throwing, transferState, secureQuality: input.secureResult.secureQuality },
    variationEvidence: { consumed: true, strength: strengthVariation, accuracy: accuracyVariation }, authority: "throwCapabilities+coarseDemand+separateVariation" });
}

function resolveTiming(args){
  const {input,opportunity,selection,throwResolution:thrown,runnerState,receiverState}=args;
  Decision.validateSelection(selection,opportunity,input);
  if(!thrown||thrown.identity!==`${selection.identity}|throw-v1`||thrown.decisionIdentity!==selection.identity
    ||thrown.throwerId!==selection.defenderId||thrown.throwerPosition!==selection.position
    ||["routeId","targetRunnerId","targetBase","receiverId","receiverPosition"].some(key=>thrown[key]!==selection.route[key]))fail("stale throw / receiver / target");
  const base={version:VERSION,identity:`${thrown.identity}|timing-v1`,decisionIdentity:selection.identity,throwIdentity:thrown.identity,
    targetRunnerId:thrown.targetRunnerId,targetBase:thrown.targetBase,receiverId:thrown.receiverId,
    authority:"resolvedThrow+existingRunnerPhysicalState+receiverReadiness",variationEvidence:{consumed:false}};
  if(selection.route.action==="holdBall"){
    if(thrown.throwAttempted!==false)fail("hold includes throw");
    return freeze({...base,contestAvailable:false,timingClassification:"noContest",timingMargin:null,
      runnerArrival:null,ballArrival:null,receiverCompletion:null,reason:"heldBall"});
  }
  const current=(input.runnerPhysicalStates||[]).find(r=>r.runnerId===thrown.targetRunnerId);
  if(!current||!same(current,runnerState)||current.targetBase!==thrown.targetBase
    ||(current.originBase==="batter"?input.batterRunnerId!==current.runnerId:input.runners[Number(current.originBase)-1]!==current.runnerId))fail("stale runner physical state");
  const forced=Force.getForcedMovement(opportunity.context.forceChain,current.runnerId);
  if(!forced&&!Decision.isAdvancingTo(current,thrown.targetBase))fail("runner not in contest");
  if(!receiverState||receiverState.receiverId!==thrown.receiverId||!same(receiverState,input.receiverState))fail("stale receiver completion");
  const runnerArrival=deriveRunnerArrival(current);
  const noContest=!thrown.throwAttempted||thrown.throwQuality==="offline"||receiverState.ready!==true;
  const receiveDelay=Number(receiverState.receiveDelay??0),tagDelay=Number(receiverState.tagDelay??1);
  if(!Number.isFinite(receiveDelay)||receiveDelay<0||!Number.isFinite(tagDelay)||tagDelay<0)fail("invalid receiver delay");
  if(noContest)return freeze({...base,contestAvailable:false,timingClassification:"noContest",timingMargin:null,
    runnerArrival,ballArrival:{quality:thrown.throwQuality},receiverCompletion:{...clone(receiverState),status:"unavailableReceive"},reason:"unusableThrowOrReceiver"});
  const qualityDelay={onTarget:0,challengingReceive:1,lateWeakThrow:3}[thrown.throwQuality];
  if(qualityDelay===undefined)fail("generic timing cannot reinterpret legacy composite throw");
  const distanceDelay={short:0,medium:1,long:2}[thrown.throwDemand?.distanceClass];
  if(distanceDelay===undefined)fail("missing throw distance");
  const ballTime=4+distanceDelay+qualityDelay+(thrown.releaseQuality==="delayedRelease"?1:0);
  const completionTime=ballTime+receiveDelay;
  const margin=Math.round((runnerArrival.relativeArrival-completionTime)*1000)/1000;
  return freeze({...base,contestAvailable:true,timingClassification:classify(margin),timingMargin:margin,runnerArrival,
    ballArrival:{relativeArrival:ballTime,quality:thrown.throwQuality,releaseQuality:thrown.releaseQuality,distanceClass:thrown.throwDemand.distanceClass},
    receiverCompletion:{...clone(receiverState),status:thrown.throwQuality==="challengingReceive"?"challengedReceive":"readyReceive",
      relativeCompletion:completionTime,tagCompletion:completionTime+tagDelay},reason:"physicalArrivalComparison"});
}

function admitSituation(situation, input = {}) {
  const routes = normalizeRoutes(situation.legalRoutes);
  const meaningfulRouteIds = [...new Set(routes.map(route => route.routeId || route.id || route.matchDecision).filter(Boolean))];
  const supported = input.supported !== false;
  const playerOwnsDecision = input.playerOwnsDecision === true;
  const admittedToPlayer = supported && playerOwnsDecision && meaningfulRouteIds.length >= 2;
  const mode = !supported ? "unsupportedFallback" : admittedToPlayer ? "playerDecision"
    : meaningfulRouteIds.length <= 1 ? "automaticResolution" : "aiDecision";
  const reason = input.reason || (admittedToPlayer ? "multipleBehaviorallyDistinctPlayerRoutes"
    : !supported ? "unsupportedSituation"
      : meaningfulRouteIds.length <= 1 ? "fewerThanTwoMeaningfulRoutes" : "playerDecisionOwnershipDenied");
  return transition(situation, "admitted", {
    admission: { mode, admittedToPlayer, reason, meaningfulRouteCount: meaningfulRouteIds.length }
  }, { reason });
}

function resolveSituation(situation, input = {}) {
  if (situation.lifecycleState === "reassessing" && situation.reassessmentState?.requiresDecision) {
    throw new Error("cannot resolve while reassessment decision is pending");
  }
  return transition(situation, "resolved", {
    resolution: {
      physicalOutcomeRef: input.physicalOutcomeRef || "",
      outsDelta: Number(input.outsDelta) || 0,
      runsDelta: Number(input.runsDelta) || 0,
      runnerActorOutcomes: clone(input.runnerActorOutcomes || []),
      executionEvidence: clone(input.executionEvidence || null),
      reason: input.reason || "physicalExecutionComplete"
    },
    executionState: { ...clone(situation.executionState || {}), status: "complete" }
  }, { phase: situation.phase, reason: input.reason || "physicalExecutionComplete" });
}

