      match.playerContribution={strong:participated&&tier==="strong"?3:0,mixed:0,failure:participated&&tier!=="strong"?3:0,runsCreated:0,runsScored:0,hits:participated&&tier==="strong"?1:0,walks:0,outsCreated:0,errors:0};
